"use client";

import dynamic from "next/dynamic";
import { usePathname } from "next/navigation";
import { useEffect, useState, type ComponentType } from "react";
import { createPortal } from "react-dom";

/**
 * Mounts the LIVE free-tool component into the tool page's panel.
 *
 * The page is design markup (an HTML string, see tools/nxm/native/tools-tool),
 * so the tool is portaled into the element it provides:
 * `<div class="tt-app" data-tool-app="<slug>">`. The components are the live
 * site's own (components/marketing/tools/*) — same endpoints, same logic —
 * and are only restyled by CSS scoped to `.tt-app`. The size calculator is
 * the new site's own UI (ToolSizeCalculator) because it has to end in a real
 * plan with a deploy link. Each tool is its own chunk, loaded only on its page.
 */
const pick = <T extends Record<string, unknown>>(p: Promise<T>, name: keyof T) => p.then((m) => m[name] as ComponentType);
const TOOLS: Record<string, ComponentType> = {
  "base64": dynamic(() => pick(import("@/components/marketing/tools/Base64Tool"), "Base64Tool"), { ssr: false }),
  "dns-lookup": dynamic(() => pick(import("@/components/marketing/tools/DnsTool"), "DnsTool"), { ssr: false }),
  "domain-generator": dynamic(() => pick(import("@/components/marketing/tools/DomainGeneratorTool"), "DomainGeneratorTool"), { ssr: false }),
  "hash-generator": dynamic(() => pick(import("@/components/marketing/tools/HashGeneratorTool"), "HashGeneratorTool"), { ssr: false }),
  "http-headers": dynamic(() => pick(import("@/components/marketing/tools/HttpHeadersTool"), "HttpHeadersTool"), { ssr: false }),
  "json-formatter": dynamic(() => pick(import("@/components/marketing/tools/JsonFormatterTool"), "JsonFormatterTool"), { ssr: false }),
  "latency-test": dynamic(() => pick(import("@/components/marketing/tools/LatencyTestTool"), "LatencyTestTool"), { ssr: false }),
  "minecraft-server-status": dynamic(() => pick(import("@/components/marketing/tools/MinecraftStatusTool"), "MinecraftStatusTool"), { ssr: false }),
  "my-ip": dynamic(() => pick(import("@/components/marketing/tools/MyIpTool"), "MyIpTool"), { ssr: false }),
  "password-generator": dynamic(() => pick(import("@/components/marketing/tools/PasswordGeneratorTool"), "PasswordGeneratorTool"), { ssr: false }),
  "port-checker": dynamic(() => pick(import("@/components/marketing/tools/PortCheckerTool"), "PortCheckerTool"), { ssr: false }),
  "server-size-calculator": dynamic(() => pick(import("./ToolSizeCalculator"), "ToolSizeCalculator"), { ssr: false }),
  "ssl-checker": dynamic(() => pick(import("@/components/marketing/tools/SslCheckerTool"), "SslCheckerTool"), { ssr: false }),
  "subnet-calculator": dynamic(() => pick(import("@/components/marketing/tools/SubnetCalculatorTool"), "SubnetCalculatorTool"), { ssr: false }),
  "uuid-generator": dynamic(() => pick(import("@/components/marketing/tools/UuidGeneratorTool"), "UuidGeneratorTool"), { ssr: false }),
  "whois": dynamic(() => pick(import("@/components/marketing/tools/WhoisTool"), "WhoisTool"), { ssr: false }),
};

export function ToolMount() {
  const pathname = usePathname();
  const [slot, setSlot] = useState<{ host: HTMLElement; slug: string } | null>(null);

  useEffect(() => {
    let layer: HTMLElement | null = null;
    const attach = () => {
      const app = document.querySelector<HTMLElement>(".tt-app[data-tool-app]");
      if (!app) return false;
      const slug = app.dataset.toolApp ?? "";
      if (!TOOLS[slug]) return true; // unknown tool: leave the page's own fallback
      layer = document.createElement("div");
      layer.className = "tt-mount";
      app.appendChild(layer);
      app.classList.add("on");
      setSlot({ host: layer, slug });
      return true;
    };
    // the page markup can stream in after this layout-level effect runs
    let mo: MutationObserver | null = null;
    if (!attach()) {
      mo = new MutationObserver(() => { if (attach()) mo?.disconnect(); });
      mo.observe(document.body, { childList: true, subtree: true });
    }
    return () => {
      mo?.disconnect();
      layer?.parentElement?.classList.remove("on");
      layer?.remove();
      setSlot(null);
    };
  }, [pathname]);

  if (!slot) return null;
  const Tool = TOOLS[slot.slug];
  return createPortal(<Tool />, slot.host);
}
import "server-only";
import { notFound } from "next/navigation";
import { WORKLOADS } from "@/lib/tools/server-sizing";
import { AU_ICONS } from "../_aurora/icons";
import { esc, gameTiers, introSpan, nxmHref, usd, vpsPlans, type GameTier, type NxmLoad, type VpsPlan } from "./lib";
import { gameRoute } from "./games-lib";
import { catalogTool, modeLabel, stagedHref, tile, toolContent, type ToolContent } from "./tools-live";

/**
 * /tools/<tool> — one native template for all 16 free tools
 * (tools/nxm/routes/tools-tool.json). Copy + SEO come from the live tool page
 * (tools-live.ts); the tool itself is the LIVE component, mounted into
 * `.tt-app` on the client by app/nxm/tools/layout.tsx -> ToolMount. The size
 * calculator is the one exception: it gets its own Aurora UI
 * (ToolSizeCalculator) because its recommendation must end in a real plan
 * with a real deploy link, fed here from the same catalogue checkout sells.
 */

async function content(p: Record<string, string>): Promise<ToolContent> {
  const c = p.tool ? await toolContent(p.tool) : null;
  if (!c) notFound();
  return c;
}

const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
const ARW = `<span class="nxm-arw" aria-hidden="true">→</span>`;
/** The library's button hierarchy, as the porter writes it (nxmlib.swap_buttons). */
const primary = (href: string, label: string) =>
  `<a class="nxm-btn${/^(deploy|get started|order|buy|launch)/i.test(label) ? " au-hov" : ""}" href="${esc(href)}">${/^(deploy|get started|order|buy|launch)/i.test(label) ? ROCKET : ""}<span class="nxm-bt">${esc(label)}</span>${ARW}</a>`;
const glass = (href: string, label: string) => `<a class="nxm-glassbtn" href="${esc(href)}"><span class="nxm-bt">${esc(label)}</span></a>`;

const cents = (dollars: number) => Math.round(dollars * 100);
/** Lowest real monthly price (intro where a plan really has one). */
const fromLine = (label: string, rows: { p: number; i: number | null }[]) => {
  if (!rows.length) return "";
  const low = Math.min(...rows.map((r) => cents(r.i ?? r.p)));
  return `<small class="tt-from">${esc(label)} from <b>${usd(low)}</b>/mo</small>`;
};

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const c = await content(p);
  const t = c.tool;
  const [vps, mc] = await Promise.all([vpsPlans(), c.cta?.productRoute ? gameTiers(c.cta.productRoute) : Promise.resolve([] as GameTier[])]);
  if (!vps.length) throw new Error("nxm /tools: no active VPS plans");

  const facts = ["Free", "No signup", t.serverSide ? "Live results, nothing mocked" : "Runs 100% in your browser"];
  const about = c.about.map((b) => `<h2>${esc(b.heading)}</h2>${b.html}`).join("");
  const steps = c.steps.map((s) => `<li><span>${s.title ? `<b>${esc(s.title)}</b>` : ""}${esc(s.body)}</span></li>`).join("");
  const faq = c.faq.map((f, i) => `<details${i === 0 ? " open" : ""}><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join("");
  const related = `<div class="tt-rels">${c.related.map((slug) => {
    const r = catalogTool(slug);
    if (!r) return "";
    return `<a class="au-card tt-rc" href="${nxmHref(`/tools/${r.slug}`)}">${tile(r)}<h3>${esc(r.name)}</h3><p>${esc(r.tagline)}</p><span class="go">Open tool <span aria-hidden="true">→</span></span></a>`;
  }).join("")}</div>`;

  // the conversion block: the live page's own where it has one (Minecraft),
  // otherwise the live ToolShell's "Need a real server?" card
  const cta = c.cta
    ? { title: c.cta.title, copy: c.cta.copy, buttons: primary(stagedHref(c.cta.primary.href), c.cta.primary.label) + glass(stagedHref(c.cta.secondary.href), c.cta.secondary.label), from: fromLine("Minecraft servers", mc) }
    : { title: "Need a real server?", copy: "Nxeon ships NVMe cloud VPS with full root access, a dedicated IPv4, and one-click apps — deployed in under a minute.", buttons: primary(nxmHref("/vps"), "Explore VPS hosting") + glass(nxmHref("/pricing"), "Compare plans"), from: fromLine("Cloud VPS", vps) };

  return {
    slots: {
      "tool.slug": t.slug, "tool.name": t.name, "tool.tagline": t.tagline, "tool.crumb": c.crumb,
      "tool.category": c.category, "tool.title": c.title, "tool.description": c.description,
      "facts:html": `<ul class="tt-facts">${facts.map((f) => `<li>${esc(f)}</li>`).join("")}</ul>`,
      "tile:html": tile(t),
      "mode:html": `<span class="au-chip${t.serverSide ? " srv" : ""}"><span class="d" aria-hidden="true"></span>${modeLabel(t)}</span>`,
      "about:html": about, "steps:html": steps, "faq:html": faq, "related:html": related,
      "cta.title": cta.title, "cta.copy": cta.copy, "cta.buttons:html": cta.buttons, "cta.from:html": cta.from,
    },
    data: t.slug === "server-size-calculator" ? await sizeCalcData(vps) : undefined,
    jsonLd: c.jsonLd,
    crumb: c.crumb,
  };
}

export async function meta(p: Record<string, string>) {
  const c = await content(p);
  return { title: c.metaTitle, description: c.metaDescription, crumb: c.crumb };
}

// ── server size calculator: real plans, real tiers, real deploy links ──────
export type CalcPlan = {
  id: string; name: string; cpu: number; ramMB: number; disk: number; slots: number | null;
  /** regular monthly price, dollars */ price: number; /** intro monthly price, dollars */ intro: number | null; introSpan: string | null;
  href: string;
};
export type CalcData = {
  calc: {
    vps: CalcPlan[];
    /** workload id -> the game family's managed tiers (only families checkout sells) */
    tiers: Record<string, { family: string; tiers: CalcPlan[] }>;
    /** workload id -> its product page */
    product: Record<string, string>;
    pricing: string; vpsPage: string;
  };
};
const fromVps = (p: VpsPlan): CalcPlan => ({
  id: p.id, name: p.n, cpu: p.cpu, ramMB: Math.round(p.ram * 1024), disk: p.disk, slots: null,
  price: p.p, intro: p.i, introSpan: p.i == null ? null : introSpan(p.it), href: p.href,
});
const fromTier = (g: GameTier): CalcPlan => ({
  id: g.id, name: g.name, cpu: g.cpu, ramMB: Math.round(g.ram * 1024), disk: g.disk, slots: g.slots,
  price: g.p, intro: g.i, introSpan: g.i == null ? null : introSpan(g.it), href: g.href,
});

async function sizeCalcData(vps: VpsPlan[]): Promise<CalcData> {
  const all = await gameTiers();
  const byFamily = new Map<string, GameTier[]>();
  for (const g of all) byFamily.set(g.family, [...(byFamily.get(g.family) ?? []), g]);
  // a game workload's family = the family whose live product page it links to
  const familyOfRoute = new Map<string, string>();
  for (const f of byFamily.keys()) { const r = gameRoute(f); if (r) familyOfRoute.set(r, f); }
  const tiers: CalcData["calc"]["tiers"] = {};
  const product: Record<string, string> = {};
  for (const w of WORKLOADS) {
    product[w.id] = stagedHref(w.productHref);
    const fam = w.group === "Game servers" ? familyOfRoute.get(w.productHref) : undefined;
    if (fam) tiers[w.id] = { family: fam, tiers: byFamily.get(fam)!.map(fromTier) };
  }
  return { calc: { vps: vps.map(fromVps), tiers, product, pricing: nxmHref("/pricing"), vpsPage: nxmHref("/vps") } };
}
