/**
 * Minecraft skin texture model — pure, DOM-free, unit-tested
 * (test/skin-core.test.ts). Everything the skin creator knows about the
 * 64×64 texture lives here: where each body part's faces sit for the classic
 * (4px arms) and slim (3px arms) models, which texels are used at all, the
 * left/right mirror of every texel, the legacy 64×32 → 64×64 conversion,
 * flood fill / line / rect rasterising, region flip/rotate/move, PNG header
 * parsing and the validation rules shared by the browser editor and the
 * username-import route (app/api/tools/mc-skin).
 *
 * Face naming is the player's own perspective (the convention on the
 * Minecraft wiki): a part's "right" face is the rectangle at (u, v+d) — the
 * player's right-hand side — and "left" is the one at (u+d+w, v+d). The 3D
 * viewer (skinview3d) maps the same rectangles, so a texel located here is
 * exactly the texel drawn on the model.
 *
 * Pixels are RGBA, row-major, 4 bytes per texel (the layout of ImageData).
 */

export const SKIN_SIZE = 64;
export type Pixels = Uint8ClampedArray;
export type Rgba = [number, number, number, number];
export type ModelType = "classic" | "slim";
export type PartId = "head" | "body" | "rightArm" | "leftArm" | "rightLeg" | "leftLeg";
export type Layer = "base" | "overlay";
export type FaceId = "top" | "bottom" | "right" | "front" | "left" | "back";
export type Rect = { x: number; y: number; w: number; h: number };

export const PARTS: PartId[] = ["head", "body", "rightArm", "leftArm", "rightLeg", "leftLeg"];
export const FACES: FaceId[] = ["top", "bottom", "right", "front", "left", "back"];
export const LAYERS: Layer[] = ["base", "overlay"];

export const PART_LABEL: Record<PartId, string> = {
  head: "Head", body: "Body", rightArm: "Right arm", leftArm: "Left arm", rightLeg: "Right leg", leftLeg: "Left leg",
};
export const OVERLAY_LABEL: Record<PartId, string> = {
  head: "Hat", body: "Jacket", rightArm: "Right sleeve", leftArm: "Left sleeve", rightLeg: "Right pants", leftLeg: "Left pants",
};
export const FACE_LABEL: Record<FaceId, string> = {
  top: "Top", bottom: "Bottom", right: "Right", front: "Front", left: "Left", back: "Back",
};

/** Texture origin (u, v) of each part's base and overlay box. */
const ORIGIN: Record<PartId, Record<Layer, [number, number]>> = {
  head: { base: [0, 0], overlay: [32, 0] },
  body: { base: [16, 16], overlay: [16, 32] },
  rightArm: { base: [40, 16], overlay: [40, 32] },
  leftArm: { base: [32, 48], overlay: [48, 48] },
  rightLeg: { base: [0, 16], overlay: [0, 32] },
  leftLeg: { base: [16, 48], overlay: [0, 48] },
};

/** Box dimensions in texels (width × height × depth). */
export function partSize(part: PartId, model: ModelType): { w: number; h: number; d: number } {
  if (part === "head") return { w: 8, h: 8, d: 8 };
  if (part === "body") return { w: 8, h: 12, d: 4 };
  if (part === "rightArm" || part === "leftArm") return { w: model === "slim" ? 3 : 4, h: 12, d: 4 };
  return { w: 4, h: 12, d: 4 };
}

/** The six face rectangles of one part's box on one layer. */
export function faceRects(part: PartId, layer: Layer, model: ModelType): Record<FaceId, Rect> {
  const [u, v] = ORIGIN[part][layer];
  const { w, h, d } = partSize(part, model);
  return {
    top: { x: u + d, y: v, w, h: d },
    bottom: { x: u + d + w, y: v, w, h: d },
    right: { x: u, y: v + d, w: d, h },
    front: { x: u + d, y: v + d, w, h },
    left: { x: u + d + w, y: v + d, w: d, h },
    back: { x: u + 2 * d + w, y: v + d, w, h },
  };
}

/** Bounding rectangle of a part's whole unwrapped box on one layer. */
export function partBounds(part: PartId, layer: Layer, model: ModelType): Rect {
  const [u, v] = ORIGIN[part][layer];
  const { w, h, d } = partSize(part, model);
  return { x: u, y: v, w: 2 * (w + d), h: d + h };
}

export type Region = { part: PartId; layer: Layer; face: FaceId; rect: Rect };

const regionCache = new Map<ModelType, Region[]>();
/** Every face rectangle of every part on both layers (36 regions). */
export function allRegions(model: ModelType): Region[] {
  let r = regionCache.get(model);
  if (!r) {
    r = [];
    for (const layer of LAYERS) for (const part of PARTS) {
      const rects = faceRects(part, layer, model);
      for (const face of FACES) r.push({ part, layer, face, rect: rects[face] });
    }
    regionCache.set(model, r);
  }
  return r;
}

export type TexelInfo = { part: PartId; layer: Layer; face: FaceId; rect: Rect; fx: number; fy: number };

const inRect = (r: Rect, x: number, y: number) => x >= r.x && y >= r.y && x < r.x + r.w && y < r.y + r.h;

/** Which part/layer/face a texel belongs to, or null for an unused texel. */
export function locateTexel(x: number, y: number, model: ModelType): TexelInfo | null {
  for (const g of allRegions(model)) {
    if (inRect(g.rect, x, y)) return { part: g.part, layer: g.layer, face: g.face, rect: g.rect, fx: x - g.rect.x, fy: y - g.rect.y };
  }
  return null;
}

export const isTexelUsed = (x: number, y: number, model: ModelType) => locateTexel(x, y, model) !== null;

const COUNTERPART: Record<PartId, PartId> = {
  head: "head", body: "body", rightArm: "leftArm", leftArm: "rightArm", rightLeg: "leftLeg", leftLeg: "rightLeg",
};
const MIRROR_FACE: Record<FaceId, FaceId> = { top: "top", bottom: "bottom", right: "left", left: "right", front: "front", back: "back" };

/**
 * The texel that mirrors (x, y) across the model's vertical centre plane:
 * the counterpart limb (right ↔ left; head and body map onto themselves),
 * the opposite side face, the column flipped within its face. Same layer.
 * Null for unused texels.
 */
export function mirrorTexel(x: number, y: number, model: ModelType): [number, number] | null {
  const t = locateTexel(x, y, model);
  if (!t) return null;
  const r = faceRects(COUNTERPART[t.part], t.layer, model)[MIRROR_FACE[t.face]];
  return [r.x + (r.w - 1 - t.fx), r.y + t.fy];
}

// ── pixel helpers ──────────────────────────────────────────────────────────
export const blankPixels = (): Pixels => new Uint8ClampedArray(SKIN_SIZE * SKIN_SIZE * 4);
export const idx = (x: number, y: number) => (y * SKIN_SIZE + x) * 4;
export const inBounds = (x: number, y: number) => x >= 0 && y >= 0 && x < SKIN_SIZE && y < SKIN_SIZE;

export function getPixel(p: Pixels, x: number, y: number): Rgba {
  const i = idx(x, y);
  return [p[i], p[i + 1], p[i + 2], p[i + 3]];
}
export function setPixel(p: Pixels, x: number, y: number, c: Rgba) {
  if (!inBounds(x, y)) return;
  const i = idx(x, y);
  p[i] = c[0]; p[i + 1] = c[1]; p[i + 2] = c[2]; p[i + 3] = c[3];
}
/** Source-over blend of `c` onto the texel (used for translucent overlay paint). */
export function blendPixel(p: Pixels, x: number, y: number, c: Rgba) {
  if (!inBounds(x, y)) return;
  if (c[3] >= 255) return setPixel(p, x, y, c);
  const i = idx(x, y);
  const sa = c[3] / 255, da = p[i + 3] / 255;
  const oa = sa + da * (1 - sa);
  if (oa <= 0) { p[i] = p[i + 1] = p[i + 2] = p[i + 3] = 0; return; }
  for (let k = 0; k < 3; k++) p[i + k] = Math.round((c[k] * sa + p[i + k] * da * (1 - sa)) / oa);
  p[i + 3] = Math.round(oa * 255);
}
export const sameColor = (a: Rgba, b: Rgba) => a[0] === b[0] && a[1] === b[1] && a[2] === b[2] && a[3] === b[3];

// ── rasterising ────────────────────────────────────────────────────────────
/** Bresenham line, inclusive of both ends. */
export function linePoints(x0: number, y0: number, x1: number, y1: number): [number, number][] {
  const pts: [number, number][] = [];
  const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
  let err = dx + dy, x = x0, y = y0;
  for (let guard = 0; guard < 512; guard++) {
    pts.push([x, y]);
    if (x === x1 && y === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x += sx; }
    if (e2 <= dx) { err += dx; y += sy; }
  }
  return pts;
}

/** Normalised rectangle spanning two corners (inclusive). */
export function rectFromCorners(x0: number, y0: number, x1: number, y1: number): Rect {
  const x = Math.min(x0, x1), y = Math.min(y0, y1);
  return { x, y, w: Math.abs(x1 - x0) + 1, h: Math.abs(y1 - y0) + 1 };
}

export function rectPoints(r: Rect, filled: boolean): [number, number][] {
  const pts: [number, number][] = [];
  for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) {
    if (filled || x === r.x || y === r.y || x === r.x + r.w - 1 || y === r.y + r.h - 1) pts.push([x, y]);
  }
  return pts;
}

/** Square brush footprint of `size` texels, anchored so odd sizes centre on the cursor. */
export function brushPoints(x: number, y: number, size: number): [number, number][] {
  const s = Math.max(1, Math.min(8, Math.floor(size)));
  const o = Math.floor((s - 1) / 2);
  const pts: [number, number][] = [];
  for (let dy = 0; dy < s; dy++) for (let dx = 0; dx < s; dx++) pts.push([x - o + dx, y - o + dy]);
  return pts;
}

/**
 * 4-connected flood fill of the colour under (x, y), confined to `bounds`
 * (the editor passes the clicked face, so paint never leaks across the
 * unrelated faces that happen to touch on the texture). Returns the filled
 * texels.
 */
export function floodFill(p: Pixels, x: number, y: number, c: Rgba, bounds: Rect): [number, number][] {
  if (!inRect(bounds, x, y)) return [];
  const target = getPixel(p, x, y);
  if (sameColor(target, c)) return [];
  const out: [number, number][] = [];
  const seen = new Uint8Array(SKIN_SIZE * SKIN_SIZE);
  const stack: [number, number][] = [[x, y]];
  while (stack.length) {
    const [cx, cy] = stack.pop()!;
    if (!inRect(bounds, cx, cy)) continue;
    const k = cy * SKIN_SIZE + cx;
    if (seen[k]) continue;
    seen[k] = 1;
    if (!sameColor(getPixel(p, cx, cy), target)) continue;
    setPixel(p, cx, cy, c);
    out.push([cx, cy]);
    stack.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
  }
  return out;
}

// ── region transforms (select tool) ────────────────────────────────────────
export function clampRect(r: Rect): Rect {
  const x = Math.max(0, Math.min(SKIN_SIZE, r.x)), y = Math.max(0, Math.min(SKIN_SIZE, r.y));
  const x2 = Math.max(0, Math.min(SKIN_SIZE, r.x + r.w)), y2 = Math.max(0, Math.min(SKIN_SIZE, r.y + r.h));
  return { x, y, w: x2 - x, h: y2 - y };
}

/** Copy of the texels inside `r`. */
export function readRegion(p: Pixels, r: Rect): Pixels {
  const out = new Uint8ClampedArray(r.w * r.h * 4);
  for (let y = 0; y < r.h; y++) for (let x = 0; x < r.w; x++) {
    const s = idx(r.x + x, r.y + y), d = (y * r.w + x) * 4;
    out[d] = p[s]; out[d + 1] = p[s + 1]; out[d + 2] = p[s + 2]; out[d + 3] = p[s + 3];
  }
  return out;
}

/** Write a w×h block at (x, y); texels falling off the texture are dropped. */
export function writeRegion(p: Pixels, block: Pixels, x: number, y: number, w: number, h: number) {
  for (let by = 0; by < h; by++) for (let bx = 0; bx < w; bx++) {
    const tx = x + bx, ty = y + by;
    if (!inBounds(tx, ty)) continue;
    const s = (by * w + bx) * 4, d = idx(tx, ty);
    p[d] = block[s]; p[d + 1] = block[s + 1]; p[d + 2] = block[s + 2]; p[d + 3] = block[s + 3];
  }
}

export function clearRegion(p: Pixels, r: Rect) {
  for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) if (inBounds(x, y)) setPixel(p, x, y, [0, 0, 0, 0]);
}

export function flipRegion(p: Pixels, r: Rect, axis: "h" | "v") {
  const b = readRegion(p, r);
  const out = new Uint8ClampedArray(b.length);
  for (let y = 0; y < r.h; y++) for (let x = 0; x < r.w; x++) {
    const sx = axis === "h" ? r.w - 1 - x : x, sy = axis === "v" ? r.h - 1 - y : y;
    out.set(b.subarray((sy * r.w + sx) * 4, (sy * r.w + sx) * 4 + 4), (y * r.w + x) * 4);
  }
  writeRegion(p, out, r.x, r.y, r.w, r.h);
}

/** Rotate a SQUARE region 90° in place (cw or ccw). Returns false for non-square regions. */
export function rotateRegion(p: Pixels, r: Rect, dir: "cw" | "ccw"): boolean {
  if (r.w !== r.h) return false;
  const n = r.w, b = readRegion(p, r);
  const out = new Uint8ClampedArray(b.length);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    // cw: dest(x, y) <- src(y, n-1-x); ccw: dest(x, y) <- src(n-1-y, x)
    const sx = dir === "cw" ? y : n - 1 - y, sy = dir === "cw" ? n - 1 - x : x;
    out.set(b.subarray((sy * n + sx) * 4, (sy * n + sx) * 4 + 4), (y * n + x) * 4);
  }
  writeRegion(p, out, r.x, r.y, n, n);
  return true;
}

/** Move the texels in `r` by (dx, dy), leaving transparency behind. */
export function moveRegion(p: Pixels, r: Rect, dx: number, dy: number) {
  const b = readRegion(p, r);
  clearRegion(p, r);
  writeRegion(p, b, r.x + dx, r.y + dy, r.w, r.h);
}

// ── format conversion ──────────────────────────────────────────────────────
function hasTransparency(p: Pixels, r: Rect): boolean {
  for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) if (p[idx(x, y) + 3] !== 255) return true;
  return false;
}

/**
 * A skin with NO transparency anywhere carries garbage (usually a solid
 * background) in its overlay areas; Minecraft and every viewer treat those as
 * empty. Same rule skinview-utils applies (bs-community/skinview3d#15, #93):
 * legacy skins only have a hat; modern skins have all six overlays.
 */
export function fixOpaqueOverlay(p: Pixels, legacy: boolean): boolean {
  const scan: Rect = legacy ? { x: 0, y: 0, w: 64, h: 32 } : { x: 0, y: 0, w: 64, h: 64 };
  if (hasTransparency(p, scan)) return false;
  const parts: PartId[] = legacy ? ["head"] : PARTS;
  for (const part of parts) for (const r of Object.values(faceRects(part, "overlay", "classic"))) clearRegion(p, r);
  return true;
}

/**
 * Legacy 64×32 (pre-1.8) skin → 64×64: the top half is kept, and the left arm
 * and left leg (which didn't exist separately) are the mirror of the right
 * ones — the same conversion Minecraft applies. Input is 64×32 RGBA.
 */
export function convertLegacy(src: Pixels): Pixels {
  if (src.length !== SKIN_SIZE * 32 * 4) throw new Error("convertLegacy expects 64x32 RGBA");
  const p = blankPixels();
  p.set(src, 0);
  for (const from of ["rightArm", "rightLeg"] as PartId[]) {
    for (const [face, r] of Object.entries(faceRects(from, "base", "classic")) as [FaceId, Rect][]) {
      void face;
      for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) {
        const m = mirrorTexel(x, y, "classic");
        if (m) setPixel(p, m[0], m[1], getPixel(p, x, y));
      }
    }
  }
  fixOpaqueOverlay(p, true);
  return p;
}

/**
 * Classic vs slim, read from the texture itself (for uploads, which carry no
 * metadata): a slim skin leaves the 4th arm column empty. Same columns
 * skinview-utils checks. Transparent OR solid black counts as empty.
 */
export function inferModel(p: Pixels): ModelType {
  const empty = (r: Rect) => {
    for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) {
      const [cr, cg, cb, ca] = getPixel(p, x, y);
      if (ca !== 0 && !(cr === 0 && cg === 0 && cb === 0 && ca === 255)) return false;
    }
    return true;
  };
  const slim = [{ x: 50, y: 16, w: 2, h: 4 }, { x: 54, y: 20, w: 2, h: 12 }, { x: 42, y: 48, w: 2, h: 4 }, { x: 46, y: 52, w: 2, h: 12 }].every(empty);
  return slim ? "slim" : "classic";
}

/** Count base-layer texels that aren't fully opaque — Minecraft draws those black. */
export function translucentBaseCount(p: Pixels, model: ModelType): number {
  let n = 0;
  for (const part of PARTS) for (const r of Object.values(faceRects(part, "base", model))) {
    for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) if (p[idx(x, y) + 3] !== 255) n++;
  }
  return n;
}

/** Zero every texel outside the model's layout (stray paint in unused areas). */
export function clearUnused(p: Pixels, model: ModelType) {
  for (let y = 0; y < SKIN_SIZE; y++) for (let x = 0; x < SKIN_SIZE; x++) if (!isTexelUsed(x, y, model)) setPixel(p, x, y, [0, 0, 0, 0]);
}

// ── PNG / input validation (shared with the server route) ──────────────────
export const MAX_SKIN_FILE_BYTES = 256 * 1024; // a 64×64 RGBA PNG is ~1–16 KB; 256 KB is generous
const PNG_SIG = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];

/** Width/height from a PNG's IHDR, or null if the bytes aren't a PNG. */
export function parsePngInfo(b: Uint8Array): { width: number; height: number; bitDepth: number; colorType: number } | null {
  if (b.length < 33) return null;
  for (let i = 0; i < 8; i++) if (b[i] !== PNG_SIG[i]) return null;
  // IHDR must be the first chunk: length 13, type "IHDR"
  const len = (b[8] << 24) | (b[9] << 16) | (b[10] << 8) | b[11];
  if (len !== 13 || b[12] !== 0x49 || b[13] !== 0x48 || b[14] !== 0x44 || b[15] !== 0x52) return null;
  const u32 = (o: number) => ((b[o] << 24) >>> 0) + (b[o + 1] << 16) + (b[o + 2] << 8) + b[o + 3];
  return { width: u32(16), height: u32(20), bitDepth: b[24], colorType: b[25] };
}

export type SkinFormat = "modern" | "legacy";
/** 64×64 → modern, 64×32 → legacy, anything else → an error message. */
export function skinFormat(width: number, height: number): SkinFormat | { error: string } {
  if (width === 64 && height === 64) return "modern";
  if (width === 64 && height === 32) return "legacy";
  return { error: `Skins must be 64×64 (or legacy 64×32) pixels — this image is ${width}×${height}.` };
}

/** Minecraft Java usernames: 1–16 letters, digits or underscores. */
export const USERNAME_RE = /^[A-Za-z0-9_]{1,16}$/;
export const isValidUsername = (s: string) => USERNAME_RE.test(s);

/**
 * Only texture URLs on Mojang's texture CDN are ever fetched. Returns the
 * normalised https URL or null. The session server hands out
 * `http://textures.minecraft.net/texture/<hex>`; we upgrade to https and
 * refuse anything with credentials, a port, a query or another path.
 */
export function allowedTextureUrl(raw: unknown): string | null {
  if (typeof raw !== "string" || raw.length > 200) return null;
  let u: URL;
  try { u = new URL(raw); } catch { return null; }
  if (u.protocol !== "http:" && u.protocol !== "https:") return null;
  if (u.hostname !== "textures.minecraft.net" || u.port || u.username || u.password || u.search || u.hash) return null;
  if (!/^\/texture\/[0-9a-f]{16,128}$/.test(u.pathname)) return null;
  return `https://textures.minecraft.net${u.pathname}`;
}

// ── colours ────────────────────────────────────────────────────────────────
/** #rgb, #rgba, #rrggbb or #rrggbbaa (leading # optional) → RGBA, or null. */
export function parseHex(s: string): Rgba | null {
  const m = s.trim().replace(/^#/, "");
  if (!/^[0-9a-fA-F]+$/.test(m)) return null;
  const h = (t: string) => parseInt(t, 16);
  if (m.length === 3 || m.length === 4) {
    const c = [...m].map((ch) => h(ch + ch));
    return [c[0], c[1], c[2], m.length === 4 ? c[3] : 255];
  }
  if (m.length === 6 || m.length === 8) {
    return [h(m.slice(0, 2)), h(m.slice(2, 4)), h(m.slice(4, 6)), m.length === 8 ? h(m.slice(6, 8)) : 255];
  }
  return null;
}
export function toHex(c: Rgba, withAlpha = false): string {
  const p = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
  return `#${p(c[0])}${p(c[1])}${p(c[2])}${withAlpha && c[3] !== 255 ? p(c[3]) : ""}`;
}
/** Lighten (amt > 0) or darken (amt < 0) by a fraction, keeping alpha. */
export function shade(c: Rgba, amt: number): Rgba {
  const f = (v: number) => (amt >= 0 ? v + (255 - v) * amt : v * (1 + amt));
  return [Math.round(f(c[0])), Math.round(f(c[1])), Math.round(f(c[2])), c[3]];
}

// ── base64url (share links) ────────────────────────────────────────────────
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
export function toBase64Url(b: Uint8Array): string {
  let out = "";
  for (let i = 0; i < b.length; i += 3) {
    const n = (b[i] << 16) | ((b[i + 1] ?? 0) << 8) | (b[i + 2] ?? 0);
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63];
    if (i + 1 < b.length) out += B64[(n >> 6) & 63];
    if (i + 2 < b.length) out += B64[n & 63];
  }
  return out;
}
export function fromBase64Url(s: string): Uint8Array | null {
  if (!/^[A-Za-z0-9_-]*$/.test(s) || s.length % 4 === 1) return null;
  const out: number[] = [];
  let buf = 0, bits = 0;
  for (const ch of s) {
    buf = (buf << 6) | B64.indexOf(ch);
    bits += 6;
    if (bits >= 8) { bits -= 8; out.push((buf >> bits) & 255); }
  }
  return new Uint8Array(out);
}

