/**
 * Starter skins for the skin creator — ORIGINAL art, drawn procedurally by
 * the code below (no Mojang default skins, no third-party templates, no
 * copied pixels). Deterministic: the same preset always yields the same
 * texture (seeded noise), so they are unit-testable and diff-stable.
 */
import {
  blankPixels, faceRects, partSize, setPixel, shade, PARTS,
  type FaceId, type Layer, type ModelType, type PartId, type Pixels, type Rgba,
} from "./skin-core";

export type SkinPreset = { id: string; name: string; blurb: string; model: ModelType; draw: (model: ModelType) => Pixels };

const hex = (h: string, a = 255): Rgba => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16), a];

/** Tiny seeded PRNG (mulberry32) for repeatable texture noise. */
function rng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const FACE_SHADE: Record<FaceId, number> = { top: 0.12, bottom: -0.28, right: -0.1, left: -0.1, front: 0, back: -0.06 };

class Painter {
  p = blankPixels();
  rand: () => number;
  constructor(public model: ModelType, seed: number) { this.rand = rng(seed); }
  private jitter(c: Rgba, n: number): Rgba { return n ? shade(c, (this.rand() * 2 - 1) * n) : c; }

  /** Fill every face of a part (one layer) with shaded, lightly-noised colour. */
  box(part: PartId, c: Rgba, layer: Layer = "base", noise = 0.05) {
    const rects = faceRects(part, layer, this.model);
    for (const f of Object.keys(rects) as FaceId[]) {
      const r = rects[f];
      for (let y = 0; y < r.h; y++) for (let x = 0; x < r.w; x++) setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[f]), noise));
    }
  }
  /** Horizontal band across the four side faces, rows [y0, y1) of the part's height. */
  band(part: PartId, y0: number, y1: number, c: Rgba, layer: Layer = "base", noise = 0.04) {
    const rects = faceRects(part, layer, this.model);
    for (const f of ["front", "back", "left", "right"] as FaceId[]) {
      const r = rects[f];
      for (let y = Math.max(0, y0); y < Math.min(r.h, y1); y++) for (let x = 0; x < r.w; x++) setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[f]), noise));
    }
  }
  /** Fill one face (or a sub-rect of it, in face coordinates). */
  face(part: PartId, face: FaceId, c: Rgba, layer: Layer = "base", sub?: { x: number; y: number; w: number; h: number }, noise = 0.03) {
    const r = faceRects(part, layer, this.model)[face];
    const s = sub ?? { x: 0, y: 0, w: r.w, h: r.h };
    for (let y = s.y; y < s.y + s.h; y++) for (let x = s.x; x < s.x + s.w; x++) {
      if (x < 0 || y < 0 || x >= r.w || y >= r.h) continue;
      setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[face]), noise));
    }
  }
  dot(part: PartId, face: FaceId, x: number, y: number, c: Rgba, layer: Layer = "base") {
    const r = faceRects(part, layer, this.model)[face];
    if (x >= 0 && y >= 0 && x < r.w && y < r.h) setPixel(this.p, r.x + x, r.y + y, c);
  }
  limbs(kind: "arms" | "legs", fn: (part: PartId) => void) {
    for (const part of (kind === "arms" ? ["rightArm", "leftArm"] : ["rightLeg", "leftLeg"]) as PartId[]) fn(part);
  }
  /** Simple face: eyes on row 4, optional mouth on row 6. */
  eyes(iris: Rgba, white: Rgba = hex("#f4f6ff"), mouth?: Rgba) {
    for (const x of [1, 5]) { this.dot("head", "front", x, 4, white); this.dot("head", "front", x + 1, 4, iris); }
    if (mouth) for (const x of [3, 4]) this.dot("head", "front", x, 6, mouth);
  }
  /** Hair: top, back, upper sides and a fringe row. */
  hair(c: Rgba, fringe = 1, sides = 3, back = 6) {
    this.face("head", "top", c);
    this.face("head", "back", c, "base", { x: 0, y: 0, w: 8, h: back });
    this.face("head", "left", c, "base", { x: 0, y: 0, w: 8, h: sides });
    this.face("head", "right", c, "base", { x: 0, y: 0, w: 8, h: sides });
    this.face("head", "front", c, "base", { x: 0, y: 0, w: 8, h: fringe });
  }
}

const SKIN = { light: hex("#e8b996"), mid: hex("#c68a62"), deep: hex("#8d5a3c") };

export const SKIN_PRESETS: SkinPreset[] = [
  {
    id: "nxeon-pilot", name: "Nxeon Pilot", blurb: "Navy flight suit, violet-to-blue stripes, cyan visor.", model: "classic",
    draw: (m) => {
      const s = new Painter(m, 11);
      s.box("head", SKIN.mid); s.hair(hex("#1d1a2e"), 2, 3, 7); s.eyes(hex("#3b6be8"), undefined, hex("#8a4f36"));
      s.box("body", hex("#141b3d")); s.limbs("arms", (a) => { s.box(a, hex("#141b3d")); s.band(a, 10, 12, SKIN.mid); });
      s.limbs("legs", (l) => { s.box(l, hex("#10152f")); s.band(l, 9, 12, hex("#2a2f4a")); });
      // brand stripes across the chest
      s.face("body", "front", hex("#3b6be8"), "base", { x: 0, y: 3, w: 8, h: 1 }); s.face("body", "front", hex("#7b3fef"), "base", { x: 0, y: 4, w: 8, h: 1 });
      s.face("body", "back", hex("#3b6be8"), "base", { x: 0, y: 3, w: 8, h: 1 }); s.face("body", "back", hex("#7b3fef"), "base", { x: 0, y: 4, w: 8, h: 1 });
      s.limbs("arms", (a) => s.band(a, 2, 3, hex("#7b3fef")));
      s.band("body", 7, 8, hex("#2b3366"));
      // visor on the hat layer
      s.face("head", "front", hex("#3edcf2", 190), "overlay", { x: 1, y: 3, w: 6, h: 2 }, 0);
      s.face("head", "front", hex("#c9f6ff", 220), "overlay", { x: 1, y: 3, w: 2, h: 1 }, 0);
      return s.p;
    },
  },
  {
    id: "trailblazer", name: "Trailblazer", blurb: "Forest tunic, leather belt and boots, wide-brim hat.", model: "classic",
    draw: (m) => {
      const s = new Painter(m, 23);
      s.box("head", SKIN.light); s.hair(hex("#6b3f1f"), 1, 4, 7); s.eyes(hex("#2f7d4a"), undefined, hex("#b06a4c"));
      s.box("body", hex("#3f7a3a")); s.band("body", 8, 9, hex("#5a3a1e")); s.face("body", "front", hex("#c9a23a"), "base", { x: 3, y: 8, w: 2, h: 1 }, 0);
      s.limbs("arms", (a) => { s.box(a, hex("#3f7a3a")); s.band(a, 4, 12, SKIN.light); });
      s.limbs("legs", (l) => { s.box(l, hex("#6b4a2b")); s.band(l, 8, 12, hex("#3a2614")); });
      // hat on the overlay: crown + brim band
      s.face("head", "top", hex("#7a5230"), "overlay");
      for (const f of ["front", "back", "left", "right"] as FaceId[]) s.face("head", f, hex("#7a5230"), "overlay", { x: 0, y: 0, w: 8, h: 2 });
      for (const f of ["front", "back", "left", "right"] as FaceId[]) s.face("head", f, hex("#4e3219"), "overlay", { x: 0, y: 2, w: 8, h: 1 });
      return s.p;
    },
  },
  {
    id: "star-voyager", name: "Star Voyager", blurb: "White pressure suit with an orange trim and glass helmet.", model: "classic",
    draw: (m) => {
      const s = new Painter(m, 37);
      s.box("head", SKIN.deep); s.hair(hex("#121212"), 1, 2, 5); s.eyes(hex("#3a2a1a"), undefined, hex("#5a3424"));
      s.box("body", hex("#e9edf5")); s.face("body", "front", hex("#ff8a2a"), "base", { x: 3, y: 1, w: 2, h: 3 });
      s.face("body", "front", hex("#3b6be8"), "base", { x: 1, y: 6, w: 2, h: 2 });
      s.limbs("arms", (a) => { s.box(a, hex("#e9edf5")); s.band(a, 10, 12, hex("#9aa3b8")); s.band(a, 3, 4, hex("#ff8a2a")); });
      s.limbs("legs", (l) => { s.box(l, hex("#e9edf5")); s.band(l, 9, 12, hex("#7f889c")); });
      s.band("body", 11, 12, hex("#9aa3b8"));
      // helmet shell + visor (overlay)
      s.box("head", hex("#f2f4fa", 255), "overlay", 0.03);
      s.face("head", "front", hex("#6fd8ff", 120), "overlay", { x: 1, y: 2, w: 6, h: 5 }, 0);
      s.face("head", "bottom", [0, 0, 0, 0], "overlay", undefined, 0);
      return s.p;
    },
  },
  {
    id: "iron-guard", name: "Iron Guard", blurb: "Plate armour with a crimson tabard and open-face helm.", model: "classic",
    draw: (m) => {
      const s = new Painter(m, 41);
      s.box("head", SKIN.light); s.hair(hex("#c99a4a"), 1, 3, 6); s.eyes(hex("#3d6fb0"), undefined, hex("#a35a46"));
      s.box("body", hex("#9ea6b3"), "base", 0.08); s.face("body", "front", hex("#a3242f"), "base", { x: 2, y: 0, w: 4, h: 12 });
      s.face("body", "front", hex("#e0b84a"), "base", { x: 3, y: 3, w: 2, h: 2 }, 0);
      s.limbs("arms", (a) => { s.box(a, hex("#9ea6b3"), "base", 0.08); s.band(a, 0, 4, hex("#7d8592")); s.band(a, 11, 12, hex("#5d6470")); });
      s.limbs("legs", (l) => { s.box(l, hex("#8a92a0"), "base", 0.08); s.band(l, 10, 12, hex("#4f5560")); });
      // helm (overlay) leaving the face open
      s.face("head", "top", hex("#b4bcc8"), "overlay", undefined, 0.06);
