/**
 * Starter skins for the skin creator — ORIGINAL art, drawn procedurally by
 * the code below (no Mojang default skins, no third-party templates, no
 * copied pixels). Deterministic: the same preset always yields the same
 * texture (seeded noise), so they are unit-testable and diff-stable.
 */
import {
  blankPixels, faceRects, partSize, setPixel, shade, PARTS,
  type FaceId, type Layer, type ModelType, type PartId, type Pixels, type Rgba,
} from "./skin-core";

export type SkinPreset = { id: string; name: string; blurb: string; model: ModelType; draw: (model: ModelType) => Pixels };

const hex = (h: string, a = 255): Rgba => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16), a];

/** Tiny seeded PRNG (mulberry32) for repeatable texture noise. */
function rng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const FACE_SHADE: Record<FaceId, number> = { top: 0.12, bottom: -0.28, right: -0.1, left: -0.1, front: 0, back: -0.06 };

class Painter {
  p = blankPixels();
  rand: () => number;
  constructor(public model: ModelType, seed: number) { this.rand = rng(seed); }
  private jitter(c: Rgba, n: number): Rgba { return n ? shade(c, (this.rand() * 2 - 1) * n) : c; }

  /** Fill every face of a part (one layer) with shaded, lightly-noised colour. */
  box(part: PartId, c: Rgba, layer: Layer = "base", noise = 0.05) {
    const rects = faceRects(part, layer, this.model);
    for (const f of Object.keys(rects) as FaceId[]) {
      const r = rects[f];
      for (let y = 0; y < r.h; y++) for (let x = 0; x < r.w; x++) setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[f]), noise));
    }
  }
  /** Horizontal band across the four side faces, rows [y0, y1) of the part's height. */
  band(part: PartId, y0: number, y1: number, c: Rgba, layer: Layer = "base", noise = 0.04) {
    const rects = faceRects(part, layer, this.model);
    for (const f of ["front", "back", "left", "right"] as FaceId[]) {
      const r = rects[f];
      for (let y = Math.max(0, y0); y < Math.min(r.h, y1); y++) for (let x = 0; x < r.w; x++) setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[f]), noise));
    }
  }
  /** Fill one face (or a sub-rect of it, in face coordinates). */
  face(part: PartId, face: FaceId, c: Rgba, layer: Layer = "base", sub?: { x: number; y: number; w: number; h: number }, noise = 0.03) {
    const r = faceRects(part, layer, this.model)[face];
    const s = sub ?? { x: 0, y: 0, w: r.w, h: r.h };
    for (let y = s.y; y < s.y + s.h; y++) for (let x = s.x; x < s.x + s.w; x++) {
      if (x < 0 || y < 0 || x >= r.w || y >= r.h) continue;
      setPixel(this.p, r.x + x, r.y + y, this.jitter(shade(c, FACE_SHADE[face]), noise));
    }
  }
  dot(part: PartId, face: FaceId, x: number, y: number, c: Rgba, layer: Layer = "base") {
    const r = faceRects(part, layer, this.model)[face];
    if (x >= 0 && y >= 0 && x < r.w && y < r.h) setPixel(this.p, r.x + x, r.y + y, c);
  }
  limbs(kind: "arms" | "legs", fn: (part: PartId) => void) {
    for (const part of (kind === "arms" ? ["rightArm", "leftArm"] : ["rightLeg", "leftLeg"]) as PartId[]) fn(part);
  }
  /** Simple face: eyes on row 4, optional mouth on row 6. */
  eyes(iris: Rgba, white: Rgba = hex("#f4f6ff"), mouth?: Rgba) {
    for (const x of [1, 5]) { this.dot("head", "front", x, 4, white); this.dot("head", "front", x + 1, 4, iris); }
    if (mouth) for (const x of [3, 4]) this.dot("head", "front", x, 6, mouth);
  }
  /** Hair: top, back, upper sides and a fringe row. */
  hair(c: Rgba, fringe = 1, sides = 3, back = 6) {
    this.face("head", "top", c);
    this.face("head", "back", c, "base", { x: 0, y: 0, w: 8, h: back });
    this.face("head", "left", c, "base", { x: 0, y: 0, w: 8, h: sides });
    this.face("head", "right", c, "base", { x: 0, y: 0, w: 8, h: sides });
    this.face("head", "front", c, "base", { x: 0, y: 0, w: 8, h: fringe });
  }
}

