import "server-only";
import { allowedTextureUrl, isValidUsername, parsePngInfo, skinFormat, MAX_SKIN_FILE_BYTES } from "./skin-core";

/**
 * Minecraft skin lookup by username, for the skin creator's "Import by
 * username" (route: app/api/tools/mc-skin). Unit-tested with a stubbed fetch
 * (test/skin-mojang.test.ts).
 *
 * Two fixed upstream hosts, never anything a caller can steer:
 *   1. api.mojang.com/users/profiles/minecraft/<name> → { id, name }
 *   2. sessionserver.mojang.com/session/minecraft/profile/<uuid>
 *      → properties[name=textures].value = base64 JSON with SKIN/CAPE URLs
 *   3. the texture PNGs themselves — ONLY if the URL is on
 *      textures.minecraft.net/texture/<hex> (allowedTextureUrl), fetched over
 *      https.
 * Usernames are validated against the Java rules before anything is sent;
 * the uuid is validated as 32 hex chars before it is used in a URL; every
 * request has a timeout, refuses redirects and caps the body size; the PNG
 * header is checked (signature + 64×64/64×32) before it is returned.
 *
 * Results (including "no such player") are cached in-process so repeated
 * lookups of the same name never re-hit Mojang, which rate-limits per IP.
 */

export type SkinLookupError = "invalid_username" | "unknown_username" | "no_skin" | "rate_limited" | "upstream";
export type SkinLookup =
  | { ok: true; name: string; uuid: string; model: "classic" | "slim"; skin: string; cape: string | null }
  | { ok: false; error: SkinLookupError };

type Fetch = typeof fetch;
const TIMEOUT_MS = 5000;
const MAX_JSON_BYTES = 32 * 1024;
const TTL_OK_MS = 10 * 60_000;
const TTL_MISS_MS = 2 * 60_000;
const CACHE_MAX = 500;

const cache = new Map<string, { at: number; ttl: number; v: SkinLookup }>();
export function _clearSkinCache() { cache.clear(); }

class Upstream extends Error { constructor(public kind: SkinLookupError) { super(kind); } }

async function readCapped(res: Response, max: number): Promise<Uint8Array> {
  const len = Number(res.headers.get("content-length") ?? "0");
  if (len > max) throw new Upstream("upstream");
  if (!res.body) return new Uint8Array(await res.arrayBuffer()).slice(0, max + 1);
  const reader = res.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > max) { await reader.cancel().catch(() => {}); throw new Upstream("upstream"); }
    chunks.push(value);
  }
  const out = new Uint8Array(total);
  let o = 0;
  for (const c of chunks) { out.set(c, o); o += c.byteLength; }
  return out;
}

async function get(f: Fetch, url: string, accept: string): Promise<Response> {
  const res = await f(url, {
    headers: { accept, "user-agent": "Nxeon-SkinCreator/1.0" },
    redirect: "error",
    signal: AbortSignal.timeout(TIMEOUT_MS),
    cache: "no-store",
  });
  if (res.status === 429) throw new Upstream("rate_limited");
  return res;
}

async function json(f: Fetch, url: string): Promise<unknown | null> {
  const res = await get(f, url, "application/json");
  if (res.status === 204 || res.status === 404) return null;
  if (!res.ok) throw new Upstream("upstream");
  const body = await readCapped(res, MAX_JSON_BYTES);
  try { return JSON.parse(new TextDecoder().decode(body)); } catch { throw new Upstream("upstream"); }
}

async function png(f: Fetch, url: string, kind: "skin" | "cape"): Promise<string | null> {
  const res = await get(f, url, "image/png");
  if (!res.ok) return null;
  const b = await readCapped(res, MAX_SKIN_FILE_BYTES);
  const info = parsePngInfo(b);
  if (!info) return null;
  if (kind === "skin" && typeof skinFormat(info.width, info.height) !== "string") return null;
  if (kind === "cape" && !(info.width === 64 && info.height === 32) && !(info.width === 22 && info.height === 17) && !(info.width === 46 && info.height === 22)) return null;
  return `data:image/png;base64,${Buffer.from(b).toString("base64")}`;
}

