import { NextResponse } from "next/server";
import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
import { checkRateLimit } from "@/lib/rate-limit";
import { lookupSkin } from "@/lib/skin/mojang";
import { isValidUsername } from "@/lib/skin/skin-core";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/tools/mc-skin?username=<name> — the skin creator's "Import by
 * username". Returns the player's current skin (and cape, if any) as PNG
 * data URLs plus the model type, so the browser never talks to Mojang and
 * never loads a cross-origin image (which would taint the editor canvas).
 *
 * All upstream handling — fixed hosts, timeouts, size caps, texture-host
 * allowlist, caching — is in lib/skin/mojang.ts. Here: per-IP throttle
 * (proxy-attested address, app/api/_lib/client-ip.ts) plus a global ceiling
 * on uncached lookups so a burst from many IPs can't get this box
 * rate-limited by Mojang for everyone.
 */
const STATUS: Record<string, number> = { invalid_username: 400, unknown_username: 404, no_skin: 404, rate_limited: 429, upstream: 502 };

export async function GET(req: Request) {
  const limited = toolRateLimitByIp(req, "mc-skin", { max: 20, windowMs: 60_000 });
  if (limited) return limited;
  const username = (new URL(req.url).searchParams.get("username") ?? "").trim();
  if (!isValidUsername(username)) return NextResponse.json({ ok: false, error: "invalid_username" }, { status: 400 });

  const global = checkRateLimit("tool:mc-skin:global", { max: 300, windowMs: 10 * 60_000 });
  if (!global.ok) return NextResponse.json({ ok: false, error: "rate_limited" }, { status: 429, headers: { "Retry-After": String(global.retryAfterSec) } });

  const r = await lookupSkin(username);
  if (!r.ok) return NextResponse.json(r, { status: STATUS[r.error] ?? 502 });
  return NextResponse.json(r, { headers: { "Cache-Control": "private, max-age=300" } });
}

