import { test } from "node:test";
import assert from "node:assert/strict";
import {
  allRegions, allowedTextureUrl, blankPixels, brushPoints, clearUnused, convertLegacy, faceRects, fixOpaqueOverlay,
  flipRegion, floodFill, fromBase64Url, getPixel, inferModel, isTexelUsed, isValidUsername, linePoints, locateTexel,
  mirrorTexel, moveRegion, parseHex, parsePngInfo, rectFromCorners, rectPoints, rotateRegion, setPixel, skinFormat,
  toBase64Url, toHex, translucentBaseCount, SKIN_SIZE, type Rgba,
} from "../lib/skin/skin-core.ts";
import { SKIN_PRESETS } from "../lib/skin/presets.ts";

test("layout: 36 regions per model, none overlapping, all inside 64x64", () => {
  for (const model of ["classic", "slim"] as const) {
    const seen = new Uint8Array(64 * 64);
    const regs = allRegions(model);
    assert.equal(regs.length, 36);
    for (const g of regs) for (let y = g.rect.y; y < g.rect.y + g.rect.h; y++) for (let x = g.rect.x; x < g.rect.x + g.rect.w; x++) {
      assert.ok(x < 64 && y < 64, `${g.part}/${g.face} out of bounds`);
      assert.equal(seen[y * 64 + x], 0, `${model} overlap at ${x},${y}`);
      seen[y * 64 + x] = 1;
    }
  }
});

test("layout: well-known texel positions", () => {
  assert.deepEqual(faceRects("head", "base", "classic").front, { x: 8, y: 8, w: 8, h: 8 });
  assert.deepEqual(faceRects("head", "overlay", "classic").front, { x: 40, y: 8, w: 8, h: 8 });
  assert.deepEqual(faceRects("body", "base", "classic").front, { x: 20, y: 20, w: 8, h: 12 });
  assert.deepEqual(faceRects("rightArm", "base", "classic").front, { x: 44, y: 20, w: 4, h: 12 });
  assert.deepEqual(faceRects("rightArm", "base", "slim").front, { x: 44, y: 20, w: 3, h: 12 });
  assert.deepEqual(faceRects("rightArm", "base", "slim").back, { x: 51, y: 20, w: 3, h: 12 });
  assert.deepEqual(faceRects("leftLeg", "overlay", "classic").front, { x: 4, y: 52, w: 4, h: 12 });
  assert.equal(locateTexel(10, 10, "classic")?.part, "head");
  assert.equal(locateTexel(10, 10, "classic")?.face, "front");
  assert.equal(locateTexel(0, 0, "classic"), null); // unused corner
  // slim leaves the 4th arm column unused
  assert.ok(isTexelUsed(55, 20, "classic"));
  assert.ok(!isTexelUsed(55, 20, "slim"));
});

test("mirror: an involution that swaps limbs and side faces", () => {
  for (const model of ["classic", "slim"] as const) {
    for (let y = 0; y < 64; y++) for (let x = 0; x < 64; x++) {
      const m = mirrorTexel(x, y, model);
      if (!isTexelUsed(x, y, model)) { assert.equal(m, null); continue; }
      assert.ok(m);
      assert.deepEqual(mirrorTexel(m[0], m[1], model), [x, y], `${model} ${x},${y}`);
      const a = locateTexel(x, y, model)!, b = locateTexel(m[0], m[1], model)!;
      assert.equal(a.layer, b.layer);
    }
  }
  // head front column 0 <-> column 7
  assert.deepEqual(mirrorTexel(8, 8, "classic"), [15, 8]);
  // right arm front -> left arm front, flipped
  assert.deepEqual(mirrorTexel(44, 20, "classic"), [39, 52]);
  // right leg outer side (0,20) -> left leg outer side (24..27, 52), flipped
  assert.deepEqual(mirrorTexel(0, 20, "classic"), [27, 52]);
});

test("legacy 64x32 -> 64x64 matches the Minecraft conversion", () => {
  const src = new Uint8ClampedArray(64 * 32 * 4);
  // right leg outer side, column 0 row 20 = red; right arm front column 0 = blue; transparent elsewhere
  const put = (x: number, y: number, c: Rgba) => src.set(c, (y * 64 + x) * 4);
  put(0, 20, [255, 0, 0, 255]);
  put(44, 20, [0, 0, 255, 255]);
  put(10, 10, [1, 2, 3, 255]);
  const out = convertLegacy(src);
  assert.equal(out.length, SKIN_SIZE * SKIN_SIZE * 4);
  assert.deepEqual(getPixel(out, 10, 10), [1, 2, 3, 255]); // top half kept
  assert.deepEqual(getPixel(out, 27, 52), [255, 0, 0, 255]); // flipped onto left leg outer
  assert.deepEqual(getPixel(out, 39, 52), [0, 0, 255, 255]); // flipped onto left arm front
  assert.throws(() => convertLegacy(new Uint8ClampedArray(10)));
});

test("fully opaque skins have their overlay cleared", () => {
  const p = blankPixels().fill(200);
  assert.equal(fixOpaqueOverlay(p, false), true);
  assert.equal(getPixel(p, 40, 8)[3], 0); // hat front cleared
  assert.equal(getPixel(p, 8, 8)[3], 200); // base untouched
  const q = blankPixels(); // has transparency -> untouched
  setPixel(q, 40, 8, [9, 9, 9, 255]);
  assert.equal(fixOpaqueOverlay(q, false), false);
  assert.deepEqual(getPixel(q, 40, 8), [9, 9, 9, 255]);
});

test("model inference from the 4th arm column", () => {
  const classic = blankPixels();
  for (const r of Object.values(faceRects("rightArm", "base", "classic"))) for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) setPixel(classic, x, y, [100, 100, 100, 255]);
  for (const r of Object.values(faceRects("leftArm", "base", "classic"))) for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) setPixel(classic, x, y, [100, 100, 100, 255]);
  assert.equal(inferModel(classic), "classic");
  assert.equal(inferModel(blankPixels()), "slim");
});

test("rasterising: line, rect, brush, flood fill confined to bounds", () => {
  assert.deepEqual(linePoints(0, 0, 3, 0), [[0, 0], [1, 0], [2, 0], [3, 0]]);
  assert.equal(linePoints(0, 0, 5, 3).length, 6);
  assert.deepEqual(rectFromCorners(5, 5, 2, 3), { x: 2, y: 3, w: 4, h: 3 });
  assert.equal(rectPoints({ x: 0, y: 0, w: 3, h: 3 }, false).length, 8);
  assert.equal(rectPoints({ x: 0, y: 0, w: 3, h: 3 }, true).length, 9);
  assert.equal(brushPoints(10, 10, 3).length, 9);
  assert.deepEqual(brushPoints(10, 10, 1), [[10, 10]]);
  const p = blankPixels();
  const filled = floodFill(p, 10, 10, [255, 0, 0, 255], { x: 8, y: 8, w: 8, h: 8 });
  assert.equal(filled.length, 64);
  assert.equal(getPixel(p, 7, 8)[3], 0); // didn't leak outside the face
  assert.equal(floodFill(p, 10, 10, [255, 0, 0, 255], { x: 8, y: 8, w: 8, h: 8 }).length, 0); // same colour: no-op
  assert.equal(floodFill(p, 0, 0, [1, 1, 1, 255], { x: 8, y: 8, w: 8, h: 8 }).length, 0); // start outside bounds
});

test("region transforms: flip, rotate (square only), move", () => {
  const p = blankPixels();
  setPixel(p, 0, 0, [1, 0, 0, 255]);
  flipRegion(p, { x: 0, y: 0, w: 4, h: 2 }, "h");
  assert.deepEqual(getPixel(p, 3, 0), [1, 0, 0, 255]);
  assert.equal(getPixel(p, 0, 0)[3], 0);
  flipRegion(p, { x: 0, y: 0, w: 4, h: 2 }, "v");
  assert.deepEqual(getPixel(p, 3, 1), [1, 0, 0, 255]);
  const q = blankPixels();
  setPixel(q, 0, 0, [7, 7, 7, 255]); // top-left
  assert.equal(rotateRegion(q, { x: 0, y: 0, w: 3, h: 3 }, "cw"), true);
  assert.deepEqual(getPixel(q, 2, 0), [7, 7, 7, 255]); // top-left -> top-right
  assert.equal(rotateRegion(q, { x: 0, y: 0, w: 3, h: 3 }, "ccw"), true);
  assert.deepEqual(getPixel(q, 0, 0), [7, 7, 7, 255]);
  assert.equal(rotateRegion(q, { x: 0, y: 0, w: 3, h: 2 }, "cw"), false);
  moveRegion(q, { x: 0, y: 0, w: 1, h: 1 }, 5, 6);
  assert.deepEqual(getPixel(q, 5, 6), [7, 7, 7, 255]);
  assert.equal(getPixel(q, 0, 0)[3], 0);
  moveRegion(q, { x: 5, y: 6, w: 1, h: 1 }, 100, 0); // off-texture: dropped, no throw
  assert.equal(getPixel(q, 5, 6)[3], 0);
});

test("PNG header parsing + size rules", () => {
  const ihdr = (w: number, h: number) => {
    const b = new Uint8Array(33);
    b.set([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 13, 0x49, 0x48, 0x44, 0x52]);
    b.set([w >>> 24, (w >> 16) & 255, (w >> 8) & 255, w & 255, h >>> 24, (h >> 16) & 255, (h >> 8) & 255, h & 255, 8, 6], 16);
    return b;
  };
  assert.deepEqual(parsePngInfo(ihdr(64, 64)), { width: 64, height: 64, bitDepth: 8, colorType: 6 });
  assert.equal(parsePngInfo(new Uint8Array(40)), null);
  const jpeg = ihdr(64, 64); jpeg[0] = 0xff;
  assert.equal(parsePngInfo(jpeg), null);
  assert.equal(skinFormat(64, 64), "modern");
  assert.equal(skinFormat(64, 32), "legacy");
  assert.ok(typeof skinFormat(128, 128) === "object");
  assert.ok(typeof skinFormat(64, 65) === "object");
});

test("username + texture URL allowlist", () => {
  for (const ok of ["Notch", "jeb_", "a", "ABCDEFGHIJKLMNOP"]) assert.ok(isValidUsername(ok), ok);
  for (const bad of ["", "ABCDEFGHIJKLMNOPQ", "no spaces", "../etc", "a.b", "émile", "x%2F"]) assert.ok(!isValidUsername(bad), bad);
  const hash = "a".repeat(64);
  assert.equal(allowedTextureUrl(`http://textures.minecraft.net/texture/${hash}`), `https://textures.minecraft.net/texture/${hash}`);
  assert.equal(allowedTextureUrl(`https://textures.minecraft.net/texture/${hash}`), `https://textures.minecraft.net/texture/${hash}`);
  for (const bad of [
    `https://textures.minecraft.net.evil.com/texture/${hash}`, `https://evil.com/texture/${hash}`,
    `https://textures.minecraft.net:8443/texture/${hash}`, `https://u:p@textures.minecraft.net/texture/${hash}`,
    `https://textures.minecraft.net/texture/${hash}?x=1`, `https://textures.minecraft.net/other/${hash}`,
    `file:///etc/passwd`, `https://127.0.0.1/texture/${hash}`, 42, null,
  ]) assert.equal(allowedTextureUrl(bad), null, String(bad));
});

