test("region transforms: flip, rotate (square only), move", () => {
  const p = blankPixels();
  setPixel(p, 0, 0, [1, 0, 0, 255]);
  flipRegion(p, { x: 0, y: 0, w: 4, h: 2 }, "h");
  assert.deepEqual(getPixel(p, 3, 0), [1, 0, 0, 255]);
