  assert.deepEqual(getPixel(q, 2, 0), [7, 7, 7, 255]); // top-left -> top-right
  assert.equal(rotateRegion(q, { x: 0, y: 0, w: 3, h: 3 }, "ccw"), true);
  assert.deepEqual(getPixel(q, 0, 0), [7, 7, 7, 255]);
