import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { lookupSkin, _clearSkinCache } from "../lib/skin/mojang.ts";

/** A minimal valid-header PNG of the given size (IHDR only — enough for the header checks). */
function fakePng(w: number, h: number): Uint8Array {
  const b = new Uint8Array(45);
  b.set([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 13, 0x49, 0x48, 0x44, 0x52]);
  b.set([0, 0, w >> 8, w & 255, 0, 0, h >> 8, h & 255, 8, 6], 16);
  return b;
}
const UUID = "069a79f444e94726a5befca90e38aaf5";
const HASH = "b".repeat(64);
const texProp = (skinUrl: string, slim = false, cape?: string) => Buffer.from(JSON.stringify({
  textures: { SKIN: { url: skinUrl, ...(slim ? { metadata: { model: "slim" } } : {}) }, ...(cape ? { CAPE: { url: cape } } : {}) },
})).toString("base64");

type Route = (url: string, init?: RequestInit) => Response | Promise<Response>;
function stub(routes: Record<string, Route>) {
  const calls: string[] = [];
  const f = (async (input: string | URL | Request, init?: RequestInit) => {
    const url = String(input);
    calls.push(url);
    assert.equal(init?.redirect, "error", "redirects must be refused");
    assert.ok(init?.signal, "every request needs a timeout signal");
    for (const [prefix, r] of Object.entries(routes)) if (url.startsWith(prefix)) return r(url, init);
    throw new Error(`unexpected fetch ${url}`);
  }) as typeof fetch;
  return { f, calls };
}
const jsonRes = (v: unknown, status = 200) => new Response(JSON.stringify(v), { status, headers: { "content-type": "application/json" } });

beforeEach(() => _clearSkinCache());

test("happy path: profile -> session -> texture, slim model, cape, https upgrade", async () => {
  const { f, calls } = stub({
    "https://api.mojang.com/users/profiles/minecraft/Notch": () => jsonRes({ id: UUID, name: "Notch" }),
    [`https://sessionserver.mojang.com/session/minecraft/profile/${UUID}`]: () => jsonRes({ properties: [{ name: "textures", value: texProp(`http://textures.minecraft.net/texture/${HASH}`, true, `http://textures.minecraft.net/texture/${"c".repeat(64)}`) }] }),
    [`https://textures.minecraft.net/texture/${HASH}`]: () => new Response(fakePng(64, 64)),
    [`https://textures.minecraft.net/texture/${"c".repeat(64)}`]: () => new Response(fakePng(64, 32)),
  });
  const r = await lookupSkin("Notch", f);
  assert.equal(r.ok, true);
  if (!r.ok) return;
  assert.equal(r.model, "slim");
  assert.equal(r.uuid, UUID);
  assert.match(r.skin, /^data:image\/png;base64,/);
  assert.match(r.cape ?? "", /^data:image\/png;base64,/);
  assert.equal(calls.length, 4);
  // cached: no further upstream calls
  await lookupSkin("notch", f);
  assert.equal(calls.length, 4);
});

test("invalid usernames never reach the network", async () => {
  const { f, calls } = stub({});
  for (const u of ["", "bad name", "../../x", "a".repeat(17), "x?y=1"]) {
    assert.deepEqual(await lookupSkin(u, f), { ok: false, error: "invalid_username" });
  }
  assert.equal(calls.length, 0);
});

test("unknown player (204) -> unknown_username, cached briefly", async () => {
  const { f, calls } = stub({ "https://api.mojang.com/": () => new Response(null, { status: 204 }) });
  assert.deepEqual(await lookupSkin("NoSuchPlayer", f), { ok: false, error: "unknown_username" });
  assert.deepEqual(await lookupSkin("NoSuchPlayer", f), { ok: false, error: "unknown_username" });
  assert.equal(calls.length, 1);
});

test("texture URL off the allowlist is never fetched", async () => {
  const { f, calls } = stub({
    "https://api.mojang.com/": () => jsonRes({ id: UUID, name: "Evil" }),
    "https://sessionserver.mojang.com/": () => jsonRes({ properties: [{ name: "textures", value: texProp("http://169.254.169.254/latest/meta-data") }] }),
  });
  assert.deepEqual(await lookupSkin("Evil", f), { ok: false, error: "no_skin" });
  assert.equal(calls.length, 2);
});

test("malformed uuid from upstream is rejected before building a URL", async () => {
  const { f, calls } = stub({ "https://api.mojang.com/": () => jsonRes({ id: "../../admin", name: "X" }) });
  assert.deepEqual(await lookupSkin("X", f), { ok: false, error: "upstream" });
  assert.equal(calls.length, 1);
});

test("rate limiting and wrong-size textures surface cleanly and are not cached", async () => {
  const rl = stub({ "https://api.mojang.com/": () => new Response("", { status: 429 }) });
  assert.deepEqual(await lookupSkin("Busy", rl.f), { ok: false, error: "rate_limited" });
  assert.deepEqual(await lookupSkin("Busy", rl.f), { ok: false, error: "rate_limited" });
  assert.equal(rl.calls.length, 2);

  const big = stub({
    "https://api.mojang.com/": () => jsonRes({ id: UUID, name: "Big" }),
    "https://sessionserver.mojang.com/": () => jsonRes({ properties: [{ name: "textures", value: texProp(`http://textures.minecraft.net/texture/${HASH}`) }] }),
    "https://textures.minecraft.net/": () => new Response(fakePng(128, 128)),
  });
  assert.deepEqual(await lookupSkin("Big", big.f), { ok: false, error: "upstream" });
});

test("oversized upstream bodies are cut off", async () => {
  const { f } = stub({ "https://api.mojang.com/": () => new Response("x".repeat(64 * 1024), { status: 200 }) });
  assert.deepEqual(await lookupSkin("Huge", f), { ok: false, error: "upstream" });
});

test("network failure -> upstream", async () => {
  const f = (async () => { throw new TypeError("fetch failed"); }) as unknown as typeof fetch;
  assert.deepEqual(await lookupSkin("Offline", f), { ok: false, error: "upstream" });
});

