"use client";

import type { Layer, PartId } from "@/lib/skin/skin-core";

/**
 * skinview3d (MIT, bs-community/skinview3d — bundles three.js, MIT) is
 * vendored UNMODIFIED as its UMD bundle at public/vendor/skinview3d-3.4.2/
 * (with LICENSE.txt) and loaded with a <script> tag only when the 3D preview
 * mounts — so three.js never lands in a shared chunk or on any other page,
 * and no npm dependency was added to the production tree.
 *
 * The bundle exposes `window.skinview3d` but not three.js itself, so the
 * types below are the small slice of its API the creator uses, and picking
 * (which body part / texel is under the pointer) is done here by hand:
 * Möller–Trumbore ray/triangle tests against each part's own box geometry,
 * interpolating that geometry's UVs — so a click maps to EXACTLY the texel
 * skinview3d drew there, on either model, with no layout duplication.
 */
export const SKINVIEW3D_SRC = "/vendor/skinview3d-3.4.2/skinview3d.bundle.js";

type Vec3 = { x: number; y: number; z: number; clone(): Vec3; set(x: number, y: number, z: number): Vec3; sub(v: Vec3): Vec3; normalize(): Vec3; unproject(cam: unknown): Vec3; applyMatrix4(m: Mat4): Vec3; setFromMatrixPosition(m: Mat4): Vec3 };
type Mat4 = { clone(): Mat4; invert(): Mat4 };
type Attr = { count: number; getX(i: number): number; getY(i: number): number; getZ(i: number): number };
export type SvMesh = { visible: boolean; parent: SvObject | null; matrixWorld: Mat4; geometry: { index: { count: number; getX(i: number): number } | null; attributes: { position: Attr; uv: Attr } } };
export type SvObject = { visible: boolean; parent: SvObject | null };
export type SvBodyPart = SvObject & { innerLayer: SvMesh; outerLayer: SvMesh };
export type SvAnimation = { speed: number; paused: boolean; progress: number };
export type SvViewer = {
  canvas: HTMLCanvasElement;
  camera: { position: Vec3; matrixWorld: Mat4; updateMatrixWorld(force?: boolean): void };
  scene: { updateMatrixWorld(force?: boolean): void };
  controls: { enabled: boolean; enablePan: boolean; enableZoom: boolean; enableRotate: boolean };
  playerObject: {
    skin: Record<PartId, SvBodyPart> & { setOuterLayerVisible(v: boolean): void; setInnerLayerVisible(v: boolean): void };
    backEquipment: "cape" | "elytra" | null;
  };
  globalLight: { intensity: number };
  cameraLight: { intensity: number };
  autoRotate: boolean;
  autoRotateSpeed: number;
  animation: SvAnimation | null;
  background: unknown;
  zoom: number;
  fov: number;
  loadSkin(src: HTMLCanvasElement | null, opts?: { model?: "default" | "slim" }): void;
  loadCape(src: HTMLCanvasElement | null, opts?: { backEquipment?: "cape" | "elytra" }): void;
  setSize(w: number, h: number): void;
  render(): void;
  resetCameraPose(): void;
  dispose(): void;
};
type AnimationCtor = new () => SvAnimation;
export type Sv3d = {
  SkinViewer: new (opts: Record<string, unknown>) => SvViewer;
  IdleAnimation: AnimationCtor; WalkingAnimation: AnimationCtor; RunningAnimation: AnimationCtor; FlyingAnimation: AnimationCtor;
  WaveAnimation: AnimationCtor; CrouchAnimation: AnimationCtor; HitAnimation: AnimationCtor; SwimAnimation: AnimationCtor;
};

let loading: Promise<Sv3d> | null = null;
/** Load the vendored bundle once per page. */
export function loadSkinview3d(): Promise<Sv3d> {
  const w = window as unknown as { skinview3d?: Sv3d };
  if (w.skinview3d) return Promise.resolve(w.skinview3d);
  if (!loading) {
    loading = new Promise<Sv3d>((resolve, reject) => {
      const s = document.createElement("script");
      s.src = SKINVIEW3D_SRC;
      s.async = true;
      s.onload = () => (w.skinview3d ? resolve(w.skinview3d) : reject(new Error("skinview3d missing")));
      s.onerror = () => { loading = null; s.remove(); reject(new Error("Could not load the 3D preview")); };
      document.head.appendChild(s);
    });
  }
  return loading;
}

export type AnimId = "none" | "idle" | "walk" | "run" | "fly" | "wave" | "crouch" | "hit" | "swim";
export const ANIMATIONS: { id: AnimId; label: string }[] = [
  { id: "idle", label: "Idle" }, { id: "walk", label: "Walk" }, { id: "run", label: "Run" }, { id: "fly", label: "Fly" },
  { id: "wave", label: "Wave" }, { id: "crouch", label: "Crouch" }, { id: "hit", label: "Hit" }, { id: "swim", label: "Swim" },
  { id: "none", label: "Still" },
];
export function makeAnimation(sv: Sv3d, id: AnimId): SvAnimation | null {
  switch (id) {
    case "idle": return new sv.IdleAnimation();
    case "walk": return new sv.WalkingAnimation();
    case "run": return new sv.RunningAnimation();
    case "fly": return new sv.FlyingAnimation();
    case "wave": return new sv.WaveAnimation();
    case "crouch": return new sv.CrouchAnimation();
    case "hit": return new sv.HitAnimation();
    case "swim": return new sv.SwimAnimation();
    default: return null;
  }
}

const PART_IDS: PartId[] = ["head", "body", "rightArm", "leftArm", "rightLeg", "leftLeg"];

function shown(o: SvObject | null): boolean {
  for (let n = o; n; n = n.parent) if (!n.visible) return false;
  return true;
}

export type Pick = { part: PartId; layer: Layer; x: number; y: number };

/**
 * The texel under a canvas-relative point. `layers` limits which layers can
 * be hit; `isOpaque(x, y)` lets a transparent overlay texel be "seen
 * through" (hit-testing what the user actually sees) unless the overlay is
 * the only layer being targeted — then empty overlay texels are paintable.
 */
export function pickTexel(
  v: SvViewer, px: number, py: number, w: number, h: number,
  layers: { base: boolean; overlay: boolean }, isOpaque: (x: number, y: number) => boolean,
): Pick | null {
  v.scene.updateMatrixWorld(true);
  v.camera.updateMatrixWorld(true);
  const V = v.camera.position.constructor as unknown as new (x?: number, y?: number, z?: number) => Vec3;
  const origin = new V().setFromMatrixPosition(v.camera.matrixWorld);
  const far = new V((px / w) * 2 - 1, -(py / h) * 2 + 1, 0.5).unproject(v.camera);
  const dir = far.sub(origin).normalize();
  const seeThrough = layers.base && layers.overlay;
  const hits: { t: number; pick: Pick }[] = [];

  for (const part of PART_IDS) {
    const bp = v.playerObject.skin[part];
    for (const [layer, mesh] of [["base", bp.innerLayer], ["overlay", bp.outerLayer]] as [Layer, SvMesh][]) {
      if (!layers[layer] || !shown(mesh)) continue;
      const inv = mesh.matrixWorld.clone().invert();
      const lo = origin.clone().applyMatrix4(inv);
      const ld = origin.clone().set(origin.x + dir.x, origin.y + dir.y, origin.z + dir.z).applyMatrix4(inv).sub(lo);
      const g = mesh.geometry, pos = g.attributes.position, uv = g.attributes.uv, index = g.index;
      const tris = index ? index.count / 3 : pos.count / 3;
      for (let t = 0; t < tris; t++) {
        const a = index ? index.getX(3 * t) : 3 * t, b = index ? index.getX(3 * t + 1) : 3 * t + 1, c = index ? index.getX(3 * t + 2) : 3 * t + 2;
        const hit = rayTri(lo, ld, pos, a, b, c);
        if (!hit) continue;
        const [tt, bu, bv] = hit;
        const w0 = 1 - bu - bv;
        const u = w0 * uv.getX(a) + bu * uv.getX(b) + bv * uv.getX(c);
        const vv = w0 * uv.getY(a) + bu * uv.getY(b) + bv * uv.getY(c);
        const us = [uv.getX(a), uv.getX(b), uv.getX(c)], vs = [uv.getY(a), uv.getY(b), uv.getY(c)];
        const minX = Math.round(Math.min(...us) * 64), maxX = Math.round(Math.max(...us) * 64) - 1;
        const minY = Math.round((1 - Math.max(...vs)) * 64), maxY = Math.round((1 - Math.min(...vs)) * 64) - 1;
        const x = Math.max(minX, Math.min(maxX, Math.floor(u * 64)));
        const y = Math.max(minY, Math.min(maxY, Math.floor((1 - vv) * 64)));
        if (layer === "overlay" && seeThrough && !isOpaque(x, y)) continue;
        hits.push({ t: tt, pick: { part, layer, x, y } });
      }
    }
  }
  if (!hits.length) return null;
  hits.sort((p, q) => p.t - q.t);
  return hits[0].pick;
}

/** Möller–Trumbore; returns [t, u, v] for a front-or-back hit with t > 0. */
function rayTri(o: Vec3, d: Vec3, pos: Attr, ia: number, ib: number, ic: number): [number, number, number] | null {
  const ax = pos.getX(ia), ay = pos.getY(ia), az = pos.getZ(ia);
  const e1x = pos.getX(ib) - ax, e1y = pos.getY(ib) - ay, e1z = pos.getZ(ib) - az;
  const e2x = pos.getX(ic) - ax, e2y = pos.getY(ic) - ay, e2z = pos.getZ(ic) - az;
  const px = d.y * e2z - d.z * e2y, py = d.z * e2x - d.x * e2z, pz = d.x * e2y - d.y * e2x;
  const det = e1x * px + e1y * py + e1z * pz;
  if (Math.abs(det) < 1e-9) return null;
  const inv = 1 / det;
  const tx = o.x - ax, ty = o.y - ay, tz = o.z - az;
  const u = (tx * px + ty * py + tz * pz) * inv;
  if (u < 0 || u > 1) return null;
  const qx = ty * e1z - tz * e1y, qy = tz * e1x - tx * e1z, qz = tx * e1y - ty * e1x;
  const v = (d.x * qx + d.y * qy + d.z * qz) * inv;
  if (v < 0 || u + v > 1) return null;
  const t = (e2x * qx + e2y * qy + e2z * qz) * inv;
  return t > 1e-6 ? [t, u, v] : null;
}

