  const far = new V((px / w) * 2 - 1, -(py / h) * 2 + 1, 0.5).unproject(v.camera);
  const dir = far.sub(origin).normalize();
  const seeThrough = layers.base && layers.overlay;
  const hits: { t: number; pick: Pick }[] = [];

  for (const part of PART_IDS) {
    const bp = v.playerObject.skin[part];
    for (const [layer, mesh] of [["base", bp.innerLayer], ["overlay", bp.outerLayer]] as [Layer, SvMesh][]) {
      if (!layers[layer] || !shown(mesh)) continue;
      const inv = mesh.matrixWorld.clone().invert();
      const lo = origin.clone().applyMatrix4(inv);
      const ld = origin.clone().set(origin.x + dir.x, origin.y + dir.y, origin.z + dir.z).applyMatrix4(inv).sub(lo);
      const g = mesh.geometry, pos = g.attributes.position, uv = g.attributes.uv, index = g.index;
      const tris = index ? index.count / 3 : pos.count / 3;
      for (let t = 0; t < tris; t++) {
        const a = index ? index.getX(3 * t) : 3 * t, b = index ? index.getX(3 * t + 1) : 3 * t + 1, c = index ? index.getX(3 * t + 2) : 3 * t + 2;
        const hit = rayTri(lo, ld, pos, a, b, c);
        if (!hit) continue;
        const [tt, bu, bv] = hit;
        const w0 = 1 - bu - bv;
        const u = w0 * uv.getX(a) + bu * uv.getX(b) + bv * uv.getX(c);
        const vv = w0 * uv.getY(a) + bu * uv.getY(b) + bv * uv.getY(c);
        const us = [uv.getX(a), uv.getX(b), uv.getX(c)], vs = [uv.getY(a), uv.getY(b), uv.getY(c)];
        const minX = Math.round(Math.min(...us) * 64), maxX = Math.round(Math.max(...us) * 64) - 1;
        const minY = Math.round((1 - Math.max(...vs)) * 64), maxY = Math.round((1 - Math.min(...vs)) * 64) - 1;
        const x = Math.max(minX, Math.min(maxX, Math.floor(u * 64)));
        const y = Math.max(minY, Math.min(maxY, Math.floor((1 - vv) * 64)));
        if (layer === "overlay" && seeThrough && !isOpaque(x, y)) continue;
        hits.push({ t: tt, pick: { part, layer, x, y } });
      }
    }
  }
  if (!hits.length) return null;
  hits.sort((p, q) => p.t - q.t);
  return hits[0].pick;
}

/** Möller–Trumbore; returns [t, u, v] for a front-or-back hit with t > 0. */
function rayTri(o: Vec3, d: Vec3, pos: Attr, ia: number, ib: number, ic: number): [number, number, number] | null {
  const ax = pos.getX(ia), ay = pos.getY(ia), az = pos.getZ(ia);
  const e1x = pos.getX(ib) - ax, e1y = pos.getY(ib) - ay, e1z = pos.getZ(ib) - az;
  const e2x = pos.getX(ic) - ax, e2y = pos.getY(ic) - ay, e2z = pos.getZ(ic) - az;
  const px = d.y * e2z - d.z * e2y, py = d.z * e2x - d.x * e2z, pz = d.x * e2y - d.y * e2x;
  const det = e1x * px + e1y * py + e1z * pz;
  if (Math.abs(det) < 1e-9) return null;
  const inv = 1 / det;
  const tx = o.x - ax, ty = o.y - ay, tz = o.z - az;
  const u = (tx * px + ty * py + tz * pz) * inv;
  if (u < 0 || u > 1) return null;
  const qx = ty * e1z - tz * e1y, qy = tz * e1x - tx * e1z, qz = tx * e1y - ty * e1x;
  const v = (d.x * qx + d.y * qy + d.z * qz) * inv;
  if (v < 0 || u + v > 1) return null;
  const t = (e2x * qx + e2y * qy + e2z * qz) * inv;
  return t > 1e-6 ? [t, u, v] : null;
}

