"use client";

import {
  allRegions, faceRects, isTexelUsed, SKIN_SIZE, PART_LABEL, OVERLAY_LABEL,
  type Layer, type ModelType, type PartId, type Pixels, type Rect,
} from "@/lib/skin/skin-core";

/** A 64×64 canvas holding `p` (for export and for feeding the 3D viewer). */
export function pixelsToCanvas(p: Pixels, into?: HTMLCanvasElement): HTMLCanvasElement {
  const c = into ?? document.createElement("canvas");
  c.width = SKIN_SIZE; c.height = SKIN_SIZE;
  const ctx = c.getContext("2d")!;
  ctx.putImageData(new ImageData(new Uint8ClampedArray(p), SKIN_SIZE, SKIN_SIZE), 0, 0);
  return c;
}

/** Upscaled copy with a texel grid drawn on it, for the "grid on model" view. */
export function gridTexture(src: HTMLCanvasElement, into: HTMLCanvasElement, scale = 8): HTMLCanvasElement {
  const n = SKIN_SIZE * scale;
  into.width = n; into.height = n;
  const ctx = into.getContext("2d")!;
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, n, n);
  ctx.drawImage(src, 0, 0, n, n);
  // grid only where there is paint, so empty overlay texels stay transparent
  const data = ctx.getImageData(0, 0, n, n);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (x % scale && y % scale) continue;
    const i = (y * n + x) * 4;
    if (data.data[i + 3] === 0) continue;
    data.data[i] *= 0.72; data.data[i + 1] *= 0.72; data.data[i + 2] *= 0.72;
  }
  ctx.putImageData(data, 0, 0);
  return into;
}

export type EditorOverlay = {
  model: ModelType;
  zoom: number; // CSS px per texel
  dpr: number;
  grid: boolean;
  guides: boolean;
  layerMode: "both" | Layer;
  hover: [number, number] | null;
  mirrorHover: [number, number] | null;
  preview: [number, number][] | null;
  previewColor: string;
  selection: Rect | null;
  focus: { part: PartId; layer: Layer; until: number } | null;
  colors: { checkA: string; checkB: string; unused: string; guideBase: string; guideOverlay: string; grid: string; label: string; sel: string; hover: string; focus: string };
};

/** Paint the whole editor canvas: checkerboard, texture, guides, grid, cursor, selection. */
export function drawEditor(canvas: HTMLCanvasElement, src: HTMLCanvasElement, o: EditorOverlay) {
  const s = o.zoom * o.dpr; // device px per texel
  const n = SKIN_SIZE * s;
  if (canvas.width !== n || canvas.height !== n) { canvas.width = n; canvas.height = n; }
  const ctx = canvas.getContext("2d")!;
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, n, n);

  // checkerboard behind transparent texels (2 squares per texel at high zoom)
  const cs = Math.max(2, s / 2);
  ctx.fillStyle = o.colors.checkA; ctx.fillRect(0, 0, n, n);
  ctx.fillStyle = o.colors.checkB;
  for (let y = 0, r = 0; y < n; y += cs, r++) for (let x = (r % 2) * cs; x < n; x += cs * 2) ctx.fillRect(x, y, cs, cs);

  ctx.drawImage(src, 0, 0, n, n);

  // unused texels + other-layer dimming
  ctx.fillStyle = o.colors.unused;
  for (let y = 0; y < SKIN_SIZE; y++) for (let x = 0; x < SKIN_SIZE; x++) if (!isTexelUsed(x, y, o.model)) ctx.fillRect(x * s, y * s, s, s);
  if (o.layerMode !== "both") {
    const other: Layer = o.layerMode === "base" ? "overlay" : "base";
    for (const g of allRegions(o.model)) if (g.layer === other) ctx.fillRect(g.rect.x * s, g.rect.y * s, g.rect.w * s, g.rect.h * s);
  }

  if (o.grid && o.zoom >= 5) {
    ctx.strokeStyle = o.colors.grid; ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 1; i < SKIN_SIZE; i++) { const p = Math.round(i * s) + 0.5; ctx.moveTo(p, 0); ctx.lineTo(p, n); ctx.moveTo(0, p); ctx.lineTo(n, p); }
    ctx.stroke();
  }

  if (o.guides) {
    ctx.lineWidth = Math.max(1, o.dpr);
    for (const g of allRegions(o.model)) {
      ctx.strokeStyle = g.layer === "base" ? o.colors.guideBase : o.colors.guideOverlay;
      ctx.strokeRect(g.rect.x * s + 0.5, g.rect.y * s + 0.5, g.rect.w * s - 1, g.rect.h * s - 1);
    }
    if (o.zoom >= 7) {
      ctx.fillStyle = o.colors.label;
      ctx.font = `600 ${Math.round(9 * o.dpr)}px ui-monospace, SFMono-Regular, Menlo, monospace`;
      ctx.textBaseline = "top";
      for (const layer of ["base", "overlay"] as Layer[]) for (const part of Object.keys(PART_LABEL) as PartId[]) {
        const r = faceRects(part, layer, o.model).top;
        const label = layer === "base" ? PART_LABEL[part] : OVERLAY_LABEL[part];
        const x = (r.x - (part === "head" ? 8 : 4)) * s + 3 * o.dpr, y = r.y * s + 2 * o.dpr;
        ctx.globalAlpha = 0.85;
        ctx.fillText(label.toUpperCase(), x, y, (r.x - (part === "head" ? 8 : 4) >= 0 ? (part === "head" ? 8 : 4) : 4) * s - 4 * o.dpr);
        ctx.globalAlpha = 1;
      }
    }
  }

  if (o.focus && o.focus.until > performance.now()) {
    const r = faceRects(o.focus.part, o.focus.layer, o.model);
    ctx.strokeStyle = o.colors.focus; ctx.lineWidth = 2.5 * o.dpr;
    for (const f of Object.values(r)) ctx.strokeRect(f.x * s, f.y * s, f.w * s, f.h * s);
  }

  if (o.preview?.length) {
    ctx.fillStyle = o.previewColor; ctx.globalAlpha = 0.8;
    for (const [x, y] of o.preview) ctx.fillRect(x * s, y * s, s, s);
    ctx.globalAlpha = 1;
  }

  if (o.selection) {
    const r = o.selection;
    ctx.lineWidth = Math.max(1, o.dpr);
    ctx.setLineDash([4 * o.dpr, 3 * o.dpr]);
    ctx.strokeStyle = o.colors.sel;
    ctx.strokeRect(r.x * s + 0.5, r.y * s + 0.5, r.w * s - 1, r.h * s - 1);
    ctx.setLineDash([]);
  }

  for (const [pt, alpha] of [[o.hover, 1], [o.mirrorHover, 0.55]] as const) {
    if (!pt) continue;
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = o.colors.hover; ctx.lineWidth = Math.max(1, o.dpr * 1.5);
    ctx.strokeRect(pt[0] * s + 0.5, pt[1] * s + 0.5, s - 1, s - 1);
    ctx.globalAlpha = 1;
  }
}

/**
 * Front-facing "paper doll" of a texture (head, body, arms, legs + overlay),
 * for template thumbnails and the 2D fallback when WebGL is unavailable.
 */
export function drawFrontView(ctx: CanvasRenderingContext2D, p: Pixels, model: ModelType, scale: number, ox = 0, oy = 0) {
  const src = pixelsToCanvas(p);
  ctx.imageSmoothingEnabled = false;
  const armW = model === "slim" ? 3 : 4;
  const put = (part: PartId, layer: Layer, dx: number, dy: number) => {
    const r = faceRects(part, layer, model).front;
    ctx.drawImage(src, r.x, r.y, r.w, r.h, ox + dx * scale, oy + dy * scale, r.w * scale, r.h * scale);
  };
  // layout in texels: total width 16, height 32
  const lx = 4 - armW; // arms hug the body
  for (const layer of ["base", "overlay"] as Layer[]) {
    put("head", layer, 4, 0);
    put("body", layer, 4, 8);
    put("rightArm", layer, lx, 8);
    put("leftArm", layer, 12, 8);
    put("rightLeg", layer, 4, 20);
    put("leftLeg", layer, 8, 20);
  }
}

