"use client";

import { forwardRef, useCallback, useEffect, useImperativeHandle, useRef, useState } from "react";
import type { Layer, ModelType, PartId, Pixels } from "@/lib/skin/skin-core";
import { PART_LABEL } from "@/lib/skin/skin-core";
import { ANIMATIONS, loadSkinview3d, makeAnimation, pickTexel, type AnimId, type Pick, type Sv3d, type SvViewer } from "./sv3d";
import { drawFrontView, gridTexture } from "./render2d";

export type ViewerHandle = { screenshot(): Promise<Blob | null>; resetCamera(): void };

type Props = {
  texture: HTMLCanvasElement;
  pixels: Pixels;
  revision: number;
  model: ModelType;
  cape: HTMLCanvasElement | null;
  capeRevision: number;
  paintMode: boolean;
  layerMode: "both" | Layer;
  onPick: (p: Pick, phase: "select" | "down" | "move" | "up") => void;
  onPaintModeChange: (on: boolean) => void;
};

const BACKGROUNDS = [
  { id: "none", label: "Clear", value: null },
  { id: "night", label: "Night", value: 0x0b1030 },
  { id: "studio", label: "Studio", value: 0xe7ebf4 },
  { id: "meadow", label: "Meadow", value: 0x7fb069 },
  { id: "violet", label: "Violet", value: 0x2a1a5e },
] as const;

const PARTS: PartId[] = ["head", "body", "rightArm", "leftArm", "rightLeg", "leftLeg"];

export const SkinViewer3D = forwardRef<ViewerHandle, Props>(function SkinViewer3D(props, ref) {
  const { texture, pixels, revision, model, cape, capeRevision, paintMode, layerMode, onPick, onPaintModeChange } = props;
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fallbackRef = useRef<HTMLCanvasElement>(null);
  const viewerRef = useRef<SvViewer | null>(null);
  const svRef = useRef<Sv3d | null>(null);
  const gridCanvas = useRef<HTMLCanvasElement | null>(null);
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading");
  const [anim, setAnim] = useState<AnimId>("idle");
  const [speed, setSpeed] = useState(1);
  const [paused, setPaused] = useState(false);
  const [spin, setSpin] = useState(false);
  const [bg, setBg] = useState<(typeof BACKGROUNDS)[number]["id"]>("none");
  const [light, setLight] = useState(1);
  const [showBase, setShowBase] = useState(true);
  const [showOverlay, setShowOverlay] = useState(true);
  const [parts, setParts] = useState<Record<PartId, boolean>>({ head: true, body: true, rightArm: true, leftArm: true, rightLeg: true, leftLeg: true });
  const [modelGrid, setModelGrid] = useState(false);
  const [elytra, setElytra] = useState(false);
  const [more, setMore] = useState(false);
  const live = useRef({ paintMode, layerMode, showBase, showOverlay, pixels, onPick });
  live.current = { paintMode, layerMode, showBase, showOverlay, pixels, onPick };

  // ── create the viewer (script loads lazily, once per page) ───────────────
  useEffect(() => {
    let disposed = false;
    loadSkinview3d().then((sv) => {
      if (disposed || !canvasRef.current || !hostRef.current) return;
      try {
        const { clientWidth: w, clientHeight: h } = hostRef.current;
        const v = new sv.SkinViewer({
          canvas: canvasRef.current, width: Math.max(1, w), height: Math.max(1, h),
          preserveDrawingBuffer: true, zoom: 0.82, fov: 50,
        });
        v.controls.enablePan = true;
        svRef.current = sv;
        viewerRef.current = v;
        setStatus("ready");
      } catch {
        setStatus("error");
      }
    }).catch(() => !disposed && setStatus("error"));
    return () => {
      disposed = true;
      viewerRef.current?.dispose();
      viewerRef.current = null;
    };
  }, []);

  // size follows the host box
  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const ro = new ResizeObserver(() => {
      const v = viewerRef.current;
      if (v && host.clientWidth && host.clientHeight) v.setSize(host.clientWidth, host.clientHeight);
    });
    ro.observe(host);
    return () => ro.disconnect();
  }, [status]);

  // ── texture / model sync ────────────────────────────────────────────────
  useEffect(() => {
    const v = viewerRef.current;
    if (status === "error" && fallbackRef.current) {
      const c = fallbackRef.current, ctx = c.getContext("2d")!;
      ctx.clearRect(0, 0, c.width, c.height);
      drawFrontView(ctx, pixels, model, 8, (c.width - 16 * 8) / 2, 8);
      return;
    }
    if (!v) return;
    let src = texture;
    if (modelGrid) src = gridTexture(texture, gridCanvas.current ??= document.createElement("canvas"));
    v.loadSkin(src, { model: model === "slim" ? "slim" : "default" });
  }, [texture, revision, model, status, modelGrid, pixels]);

  useEffect(() => {
    const v = viewerRef.current;
    if (!v) return;
    if (cape) v.loadCape(cape, { backEquipment: elytra ? "elytra" : "cape" });
    else v.loadCape(null);
  }, [cape, capeRevision, elytra, status]);

  // ── options ─────────────────────────────────────────────────────────────
  useEffect(() => {
    const v = viewerRef.current, sv = svRef.current;
    if (!v || !sv) return;
    const a = makeAnimation(sv, anim);
    if (a) { a.speed = speed; a.paused = paused || paintMode; }
    v.animation = a;
  }, [anim, status]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const a = viewerRef.current?.animation;
    if (a) { a.speed = speed; a.paused = paused || paintMode; }
  }, [speed, paused, paintMode, status]);

  useEffect(() => {
    const v = viewerRef.current;
    if (!v) return;
    v.autoRotate = spin && !paintMode;
    v.autoRotateSpeed = 2;
    v.background = BACKGROUNDS.find((b) => b.id === bg)?.value ?? null;
    v.globalLight.intensity = 3 * light;
    v.cameraLight.intensity = 0.6 + 0.4 * light;
    v.playerObject.skin.setInnerLayerVisible(showBase);
    v.playerObject.skin.setOuterLayerVisible(showOverlay);
    for (const p of PARTS) v.playerObject.skin[p].visible = parts[p];
  }, [spin, paintMode, bg, light, showBase, showOverlay, parts, status]);

  // ── picking: click a part to jump the editor; paint on the model ─────────
  const pick = useCallback((e: PointerEvent): Pick | null => {
    const v = viewerRef.current, host = hostRef.current;
    if (!v || !host) return null;
    const r = v.canvas.getBoundingClientRect();
    const { layerMode: lm, showBase: sb, showOverlay: so, pixels: px } = live.current;
    const layers = lm === "base" ? { base: true, overlay: false } : lm === "overlay" ? { base: false, overlay: true } : { base: sb, overlay: so };
    return pickTexel(v, e.clientX - r.left, e.clientY - r.top, r.width, r.height, layers, (x, y) => px[(y * 64 + x) * 4 + 3] > 0);
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    if (!host || status !== "ready") return;
    let painting: number | null = null;
    let down: { x: number; y: number; t: number } | null = null;
    const onDown = (e: PointerEvent) => {
      if (e.button !== 0) return;
      down = { x: e.clientX, y: e.clientY, t: performance.now() };
      if (!live.current.paintMode) return;
      const p = pick(e);
      if (!p) return; // missed the model: let the orbit controls have it
      e.stopPropagation(); e.preventDefault();
      painting = e.pointerId;
      host.setPointerCapture(e.pointerId);
      live.current.onPick(p, "down");
    };
    const onMove = (e: PointerEvent) => {
      if (painting !== e.pointerId) {
        if (live.current.paintMode) host.style.cursor = pick(e) ? "crosshair" : "grab";
        return;
      }
      e.stopPropagation();
      const p = pick(e);
      if (p) live.current.onPick(p, "move");
    };
    const onUp = (e: PointerEvent) => {
      if (painting === e.pointerId) {
        e.stopPropagation();
        painting = null;
        const p = pick(e);
        live.current.onPick(p ?? { part: "head", layer: "base", x: -1, y: -1 }, "up");
        return;
      }
      if (down && Math.hypot(e.clientX - down.x, e.clientY - down.y) < 6 && performance.now() - down.t < 500) {
        const p = pick(e);
        if (p) live.current.onPick(p, "select");
      }
      down = null;
    };
    host.addEventListener("pointerdown", onDown, true);
    host.addEventListener("pointermove", onMove, true);
    host.addEventListener("pointerup", onUp, true);
    host.addEventListener("pointercancel", onUp, true);
    return () => {
      host.removeEventListener("pointerdown", onDown, true);
      host.removeEventListener("pointermove", onMove, true);
      host.removeEventListener("pointerup", onUp, true);
      host.removeEventListener("pointercancel", onUp, true);
      host.style.cursor = "";
    };
  }, [status, pick]);

  useImperativeHandle(ref, () => ({
    async screenshot() {
      const v = viewerRef.current;
      if (!v) return null;
      v.render();
      return new Promise<Blob | null>((res) => v.canvas.toBlob((b) => res(b), "image/png"));
    },
    resetCamera() { viewerRef.current?.resetCameraPose(); },
  }), []);

  const chip = (on: boolean) => `skc-chip${on ? " on" : ""}`;

  return (
    <div className="skc-viewer">
      <div ref={hostRef} className={`skc-stage${paintMode ? " painting" : ""}`} data-bg={bg}>
        <canvas ref={canvasRef} className="skc-3d" aria-label="3D skin preview — drag to rotate, scroll or pinch to zoom, right-drag to pan, click a body part to edit it" />
        {status === "loading" && <div className="skc-stage-msg"><span className="skc-spin" aria-hidden="true" />Loading 3D preview…</div>}
        {status === "error" && (
          <div className="skc-stage-fallback">
            <canvas ref={fallbackRef} width={160} height={272} className="skc-flat" aria-label="Flat front view of the skin" />
            <p>3D preview needs WebGL, which this browser has turned off. The editor still works — this is a flat front view.</p>
          </div>
        )}
        {status === "ready" && (
          <div className="skc-stage-tools">
            <button type="button" className={chip(paintMode)} onClick={() => onPaintModeChange(!paintMode)} aria-pressed={paintMode} title="Paint directly on the 3D model (P)">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20c2.5 0 4-1.3 4-3.5 0-1.2.9-2 2-2s2 .9 2 2c0 2.8-3 3.5-8 3.5ZM12 13.5 20 5.5a1.8 1.8 0 0 0-2.5-2.5L9.5 11" /></svg>
              {paintMode ? "Painting on model" : "Paint on model"}
            </button>
            <button type="button" className="skc-chip" onClick={() => viewerRef.current?.resetCameraPose()} title="Reset camera">
              <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12a8 8 0 1 0 2.3-5.7M4 4v4h4" /></svg>Reset
            </button>
          </div>
        )}
      </div>

      <div className="skc-vctl">
        <div className="skc-row" role="group" aria-label="Animation">
          {ANIMATIONS.map((a) => (
            <button key={a.id} type="button" className={chip(anim === a.id)} aria-pressed={anim === a.id} onClick={() => setAnim(a.id)}>{a.label}</button>
          ))}
        </div>
        <div className="skc-row">
          <button type="button" className={chip(paused)} aria-pressed={paused} onClick={() => setPaused(!paused)}>{paused ? "Resume" : "Pause"}</button>
          <button type="button" className={chip(spin)} aria-pressed={spin} onClick={() => setSpin(!spin)}>Spin</button>
          <label className="skc-range"><span>Speed</span><input type="range" min={0.25} max={2.5} step={0.25} value={speed} onChange={(e) => setSpeed(Number(e.target.value))} aria-label="Animation speed" /></label>
        </div>
        <div className="skc-row">
          <button type="button" className={chip(showBase)} aria-pressed={showBase} onClick={() => setShowBase(!showBase)}>Base layer</button>
          <button type="button" className={chip(showOverlay)} aria-pressed={showOverlay} onClick={() => setShowOverlay(!showOverlay)}>Overlay</button>
          <button type="button" className={chip(modelGrid)} aria-pressed={modelGrid} onClick={() => setModelGrid(!modelGrid)}>Pixel grid</button>
          <button type="button" className="skc-chip ghost" onClick={() => setMore(!more)} aria-expanded={more}>{more ? "Fewer options" : "More options"}</button>
        </div>
        {more && (
          <>
            <div className="skc-row" role="group" aria-label="Background">
              <span className="skc-k">Background</span>
              {BACKGROUNDS.map((b) => <button key={b.id} type="button" className={chip(bg === b.id)} aria-pressed={bg === b.id} onClick={() => setBg(b.id)}>{b.label}</button>)}
            </div>
            <div className="skc-row">
              <label className="skc-range"><span>Light</span><input type="range" min={0.3} max={1.6} step={0.05} value={light} onChange={(e) => setLight(Number(e.target.value))} aria-label="Light intensity" /></label>
              {cape && <button type="button" className={chip(elytra)} aria-pressed={elytra} onClick={() => setElytra(!elytra)}>{elytra ? "Elytra" : "Cape"}</button>}
            </div>
            <div className="skc-row" role="group" aria-label="Visible body parts">
              <span className="skc-k">Show</span>
              {PARTS.map((p) => (
                <button key={p} type="button" className={chip(parts[p])} aria-pressed={parts[p]} onClick={() => setParts({ ...parts, [p]: !parts[p] })}>{PART_LABEL[p]}</button>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
});

