    if (!c) return;
    const s = st.current;
    const m = hover.current && s.mirror ? mirrorTexel(hover.current[0], hover.current[1], s.model) : null;
    drawEditor(c, tex, {
      model: s.model, zoom: s.zoom, dpr: Math.min(2, window.devicePixelRatio || 1), grid, guides, layerMode: s.layerMode,
      hover: hover.current, mirrorHover: m, preview: preview.current, previewColor: toHex(s.color), selection: s.selection,
      focus: focus.current, colors: themeColors(),
    });
  }, [tex, grid, guides, themeColors]);

  useEffect(() => { redraw(); }, [redraw, rev, model, zoom, layerMode, selection, mirror]);

  // initial texture + share-link import + recent colours
  useEffect(() => {
    pixelsToCanvas(pix.current, tex);
    setRev(1);
    try { const r = JSON.parse(storageGet(RECENT_KEY) ?? "[]"); if (Array.isArray(r)) setRecent(r.filter((x) => typeof x === "string" && parseHex(x)).slice(0, 12)); } catch { /* ignore */ }
    const m = window.location.hash.match(/(?:^#|&)skin=([A-Za-z0-9_-]{20,40000})(?:&m=(slim|classic))?/);
    if (m) {
      const bytes = fromBase64Url(m[1]);
      if (bytes) {
        decodeSkin(new Blob([bytes as BlobPart], { type: "image/png" })).then((r) => {
          if ("error" in r) return say(`Shared link: ${r.error}`, "err");
          pix.current = r.pixels;
          setModelState(m[2] === "slim" ? "slim" : m[2] === "classic" ? "classic" : inferModel(r.pixels));
          commit();
          say("Loaded the skin from the shared link.");
        });
      }
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // fit zoom to the editor width until the user zooms themselves
  useEffect(() => {
    const w = wrapRef.current;
    if (!w) return;
    const fit = () => { if (!userZoomed.current) setZoom(Math.max(4, Math.min(12, Math.floor((w.clientWidth - 2) / SKIN_SIZE)))); };
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(w);
    return () => ro.disconnect();
  }, []);

  // ── history ─────────────────────────────────────────────────────────────
  const snapshot = useCallback(() => {
    undoStack.current.push({ p: new Uint8ClampedArray(pix.current), model: st.current.model });
    if (undoStack.current.length > HISTORY_MAX) undoStack.current.shift();
    redoStack.current = [];
    setHist((h) => h + 1);
  }, []);
  const undo = useCallback(() => {
    const s = undoStack.current.pop();
    if (!s) return;
    redoStack.current.push({ p: new Uint8ClampedArray(pix.current), model: st.current.model });
    pix.current = s.p; setModelState(s.model); commit(); setHist((h) => h + 1);
  }, [commit]);
  const redo = useCallback(() => {
    const s = redoStack.current.pop();
    if (!s) return;
    undoStack.current.push({ p: new Uint8ClampedArray(pix.current), model: st.current.model });
    pix.current = s.p; setModelState(s.model); commit(); setHist((h) => h + 1);
  }, [commit]);
  void hist;

  const setModel = useCallback((m: ModelType) => {
    if (m === st.current.model) return;
    snapshot();
    setModelState(m);
    commit();
  }, [snapshot, commit]);

  const replaceSkin = useCallback((p: Pixels, m: ModelType, label: string) => {
    snapshot();
    pix.current = p;
    setModelState(m);
    setSelection(null);
    commit();
    say(label);
  }, [snapshot, commit, say]);

  // ── colours ─────────────────────────────────────────────────────────────
  const pushRecent = useCallback((c: Rgba) => {
    const h = toHex([c[0], c[1], c[2], 255]);
    setRecent((r) => {
      const next = [h, ...r.filter((x) => x !== h)].slice(0, 12);
      storageSet(RECENT_KEY, JSON.stringify(next));
      return next;
    });
  }, []);
  const chooseColor = useCallback((c: Rgba) => {
    setColor([c[0], c[1], c[2], 255]);
    if (c[3] !== 255 && c[3] > 0) setAlpha(c[3]);
    setHexDraft(toHex([c[0], c[1], c[2], 255]));
  }, []);

  const inUse = useMemo(() => {
    const counts = new Map<string, number>();
    const p = pix.current;
    for (let i = 0; i < p.length; i += 4) {
      if (p[i + 3] === 0) continue;
      const h = toHex([p[i], p[i + 1], p[i + 2], 255]);
      counts.set(h, (counts.get(h) ?? 0) + 1);
    }
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 18).map(([h]) => h);
  }, [rev]); // eslint-disable-line react-hooks/exhaustive-deps

  const translucent = useMemo(() => translucentBaseCount(pix.current, model), [rev, model]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── painting primitives ─────────────────────────────────────────────────
  const allowed = useCallback((x: number, y: number) => {
    const t = locateTexel(x, y, st.current.model);
    if (!t) return null;
    const lm = st.current.layerMode;
    if (lm !== "both" && t.layer !== lm) return null;
    return t;
  }, []);

  const touched = useRef<Set<number>>(new Set());
  const applyTexel = useCallback((x: number, y: number, t: Tool, lighten: boolean) => {
    const s = st.current;
    const targets: [number, number][] = [[x, y]];
    if (s.mirror) { const m = mirrorTexel(x, y, s.model); if (m && (m[0] !== x || m[1] !== y)) targets.push(m); }
    for (const [tx, ty] of targets) {
      const info = allowed(tx, ty);
      if (!info) continue;
      const k = ty * 64 + tx;
      if ((t === "noise" || t === "shade") && touched.current.has(k)) continue;
      touched.current.add(k);
      if (t === "eraser") { setPixel(pix.current, tx, ty, [0, 0, 0, 0]); continue; }
      const a = info.layer === "base" ? 255 : s.alpha;
      if (t === "pencil" || t === "line" || t === "rect") setPixel(pix.current, tx, ty, [s.color[0], s.color[1], s.color[2], a]);
      else if (t === "noise") setPixel(pix.current, tx, ty, shade([s.color[0], s.color[1], s.color[2], a], (Math.random() * 2 - 1) * 0.14));
      else if (t === "shade") {
        const cur = getPixel(pix.current, tx, ty);
        if (cur[3] === 0) continue;
        setPixel(pix.current, tx, ty, shade(cur, lighten ? 0.1 : -0.1));
      }
    }
  }, [allowed]);

  const stamp = useCallback((x: number, y: number, t: Tool, lighten: boolean) => {
    for (const [bx, by] of brushPoints(x, y, st.current.size)) applyTexel(bx, by, t, lighten);
  }, [applyTexel]);

  const fillAt = useCallback((x: number, y: number) => {
    const s = st.current;
    const starts: [number, number][] = [[x, y]];
    if (s.mirror) { const m = mirrorTexel(x, y, s.model); if (m) starts.push(m); }
    let n = 0;
    for (const [sx, sy] of starts) {
      const info = allowed(sx, sy);
      if (!info) continue;
      const a = info.layer === "base" ? 255 : s.alpha;
      n += floodFill(pix.current, sx, sy, [s.color[0], s.color[1], s.color[2], a], info.rect).length;
    }
    return n;
  }, [allowed]);

  const pickAt = useCallback((x: number, y: number) => {
    const c = getPixel(pix.current, x, y);
    if (c[3] === 0) return say("That texel is transparent — nothing to pick.", "err");
    chooseColor(c);
  }, [chooseColor, say]);

  // ── jump the editor to a part (from the 3D model or the chips) ──────────
  const jumpTo = useCallback((part: PartId, layer: Layer, texel?: [number, number]) => {
    const w = wrapRef.current;
    if (!w) return;
    const b = partBounds(part, layer, st.current.model);
    const z = Math.max(st.current.zoom, Math.min(18, Math.floor((w.clientWidth - 8) / (b.w + 2))));
    userZoomed.current = true;
    setZoom(z);
    focus.current = { part, layer, until: performance.now() + 1800 };
    if (texel) hover.current = texel;
    requestAnimationFrame(() => {
      w.scrollTo({ left: Math.max(0, (b.x + b.w / 2) * z - w.clientWidth / 2), top: Math.max(0, (b.y + b.h / 2) * z - w.clientHeight / 2), behavior: "smooth" });
      redraw();
      setTimeout(redraw, 1850);
    });
  }, [redraw]);

  const fitZoom = useCallback(() => {
    const w = wrapRef.current;
    userZoomed.current = false;
    if (w) setZoom(Math.max(4, Math.min(12, Math.floor((w.clientWidth - 2) / SKIN_SIZE))));
  }, []);
  const zoomBy = useCallback((d: number) => { userZoomed.current = true; setZoom((z) => Math.max(3, Math.min(24, z + d))); }, []);

  // ── 2D canvas pointer handling ──────────────────────────────────────────
  const drag = useRef<{
    id: number; tool: Tool; start: [number, number]; last: [number, number]; lighten: boolean;
    move?: { base: Pixels; block: Pixels; rect: Rect }; selecting?: boolean;
  } | null>(null);
  const pointers = useRef(new Map<number, { x: number; y: number }>());
  const pinch = useRef<{ dist: number; zoom: number; mid: { x: number; y: number }; scroll: { l: number; t: number } } | null>(null);

  const texelAt = (e: { clientX: number; clientY: number }): [number, number] | null => {
    const c = canvasRef.current;
    if (!c) return null;
    const r = c.getBoundingClientRect();
    const x = Math.floor(((e.clientX - r.left) / r.width) * SKIN_SIZE), y = Math.floor(((e.clientY - r.top) / r.height) * SKIN_SIZE);
    return x >= 0 && y >= 0 && x < SKIN_SIZE && y < SKIN_SIZE ? [x, y] : null;
  };

  const shapePoints = (t: Tool, a: [number, number], b: [number, number]) => {
    if (t === "line") return linePoints(a[0], a[1], b[0], b[1]).flatMap(([x, y]) => brushPoints(x, y, st.current.size));
    return rectPoints(rectFromCorners(a[0], a[1], b[0], b[1]), st.current.rectFill);
  };

  const onDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.current.size === 2) {
      // second finger: abandon the stroke and pinch-zoom instead
      if (drag.current) { const u = undoStack.current.pop(); if (u) { pix.current = u.p; commit(); } drag.current = null; preview.current = null; }
      const [p1, p2] = [...pointers.current.values()];
      const w = wrapRef.current!;
      pinch.current = { dist: Math.hypot(p1.x - p2.x, p1.y - p2.y), zoom: st.current.zoom, mid: { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 }, scroll: { l: w.scrollLeft, t: w.scrollTop } };
      return;
    }
    if (e.button !== 0 && e.pointerType === "mouse") return;
    const pt = texelAt(e);
    if (!pt) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    let t = st.current.tool;
    if (e.altKey && (t === "pencil" || t === "fill" || t === "noise")) t = "picker";
    if (t === "picker") { pickAt(pt[0], pt[1]); return; }
    if (t === "fill") {
      snapshot();
      if (fillAt(pt[0], pt[1]) === 0) undoStack.current.pop(); else { pushRecent(st.current.color); commit(); }
      return;
    }
    if (t === "select") {
      const sel = st.current.selection;
      if (sel && pt[0] >= sel.x && pt[1] >= sel.y && pt[0] < sel.x + sel.w && pt[1] < sel.y + sel.h) {
        snapshot();
        drag.current = { id: e.pointerId, tool: t, start: pt, last: pt, lighten: false, move: { base: new Uint8ClampedArray(pix.current), block: readRegion(pix.current, sel), rect: sel } };
      } else {
        drag.current = { id: e.pointerId, tool: t, start: pt, last: pt, lighten: false, selecting: true };
        setSelection({ x: pt[0], y: pt[1], w: 1, h: 1 });
      }
      return;
    }
    snapshot();
    touched.current = new Set();
    drag.current = { id: e.pointerId, tool: t, start: pt, last: pt, lighten: e.shiftKey };
    if (t === "line" || t === "rect") { preview.current = shapePoints(t, pt, pt); redraw(); return; }
    stamp(pt[0], pt[1], t, e.shiftKey);
    commit();
  };

  const onMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (pointers.current.has(e.pointerId)) pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pinch.current && pointers.current.size === 2) {
      const [p1, p2] = [...pointers.current.values()];
      const d = Math.hypot(p1.x - p2.x, p1.y - p2.y);
      const z = Math.max(3, Math.min(24, Math.round(pinch.current.zoom * (d / Math.max(1, pinch.current.dist)))));
      userZoomed.current = true;
      if (z !== st.current.zoom) setZoom(z);
      const w = wrapRef.current!;
      const mid = { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 };
      w.scrollLeft = pinch.current.scroll.l - (mid.x - pinch.current.mid.x);
      w.scrollTop = pinch.current.scroll.t - (mid.y - pinch.current.mid.y);
      return;
    }
    const pt = texelAt(e);
    const prevHover = hover.current;
    hover.current = pt;
    const d = drag.current;
    if (!d || d.id !== e.pointerId) {
      if (prevHover?.[0] !== pt?.[0] || prevHover?.[1] !== pt?.[1]) redraw();
      return;
    }
    if (!pt) return;
    if (pt[0] === d.last[0] && pt[1] === d.last[1]) return;
    if (d.tool === "select") {
      if (d.selecting) setSelection(rectFromCorners(d.start[0], d.start[1], pt[0], pt[1]));
      else if (d.move) {
        const dx = pt[0] - d.start[0], dy = pt[1] - d.start[1];
        pix.current.set(d.move.base);
        clearRegion(pix.current, d.move.rect);
        writeRegion(pix.current, d.move.block, d.move.rect.x + dx, d.move.rect.y + dy, d.move.rect.w, d.move.rect.h);
        setSelection(clampRect({ ...d.move.rect, x: d.move.rect.x + dx, y: d.move.rect.y + dy }));
        commit();
      }
    } else if (d.tool === "line" || d.tool === "rect") {
      preview.current = shapePoints(d.tool, d.start, pt);
      redraw();
    } else {
      for (const [x, y] of linePoints(d.last[0], d.last[1], pt[0], pt[1]).slice(1)) stamp(x, y, d.tool, d.lighten);
      commit();
    }
    d.last = pt;
  };

  const onUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
    pointers.current.delete(e.pointerId);
    if (pinch.current) { if (pointers.current.size < 2) pinch.current = null; return; }
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    if (d.tool === "line" || d.tool === "rect") {
      for (const [x, y] of shapePoints(d.tool, d.start, d.last)) applyTexel(x, y, d.tool, false);
      preview.current = null;
      pushRecent(st.current.color);
      commit();
      return;
    }
    if (d.tool === "select") {
      if (d.selecting && d.start[0] === d.last[0] && d.start[1] === d.last[1]) {
        // a click selects the whole face under the cursor
        const info = locateTexel(d.start[0], d.start[1], st.current.model);
        setSelection(info ? info.rect : null);
      }
      if (d.move && d.start[0] === d.last[0] && d.start[1] === d.last[1]) undoStack.current.pop();
      return;
    }
    if (d.tool === "pencil" || d.tool === "noise") pushRecent(st.current.color);
  };

  const onLeave = () => { if (!drag.current) { hover.current = null; redraw(); } };

  const onWheel = useCallback((e: WheelEvent) => {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    zoomBy(e.deltaY < 0 ? 1 : -1);
  }, [zoomBy]);
  useEffect(() => {
    const c = canvasRef.current;
    if (!c) return;
    c.addEventListener("wheel", onWheel, { passive: false });
    return () => c.removeEventListener("wheel", onWheel);
  }, [onWheel]);

  // ── selection actions ───────────────────────────────────────────────────
  const selAction = useCallback((kind: "flipH" | "flipV" | "rotCW" | "rotCCW" | "clear" | "mirrorCopy" | "copy" | "paste") => {
    const sel = st.current.selection;
    if (kind === "paste") {
      if (!clip.current) return say("Copy a selection first (Ctrl+C).", "err");
      const at = hover.current ?? (sel ? [sel.x, sel.y] : [0, 0]);
      snapshot();
      writeRegion(pix.current, clip.current.block, at[0], at[1], clip.current.w, clip.current.h);
      setSelection(clampRect({ x: at[0], y: at[1], w: clip.current.w, h: clip.current.h }));
      setTool("select");
      commit();
      return;
    }
    if (!sel) return;
    if (kind === "copy") { clip.current = { block: readRegion(pix.current, sel), w: sel.w, h: sel.h }; say(`Copied ${sel.w}×${sel.h} texels.`); return; }
    snapshot();
    if (kind === "flipH") flipRegion(pix.current, sel, "h");
    else if (kind === "flipV") flipRegion(pix.current, sel, "v");
    else if (kind === "rotCW" || kind === "rotCCW") {
      if (!rotateRegion(pix.current, sel, kind === "rotCW" ? "cw" : "ccw")) { undoStack.current.pop(); return say("Rotate needs a square selection (every head face is square).", "err"); }
    } else if (kind === "clear") clearRegion(pix.current, sel);
    else if (kind === "mirrorCopy") {
      const m = st.current.model;
      for (let y = sel.y; y < sel.y + sel.h; y++) for (let x = sel.x; x < sel.x + sel.w; x++) {
        const t = mirrorTexel(x, y, m);
        if (t) setPixel(pix.current, t[0], t[1], getPixel(pix.current, x, y));
      }
    }
    commit();
  }, [snapshot, commit, say]);

  // ── import / export ─────────────────────────────────────────────────────
  const importBlob = useCallback(async (blob: Blob, label: string) => {
    const r = await decodeSkin(blob);
    if ("error" in r) return say(r.error, "err");
    replaceSkin(r.pixels, inferModel(r.pixels), r.legacy ? `${label} (old 64×32 skin — converted to 64×64).` : label);
  }, [replaceSkin, say]);

  const importUsername = useCallback(async () => {
    const u = username.trim();
    if (!isValidUsername(u)) return say(ERR.invalid_username, "err");
    setBusy(true);
    try {
      const res = await fetch(`/api/tools/mc-skin?username=${encodeURIComponent(u)}`);
      const j = (await res.json().catch(() => null)) as { ok?: boolean; error?: string; name?: string; model?: ModelType; skin?: string; cape?: string | null } | null;
      if (!res.ok || !j?.ok || !j.skin) return say(ERR[j?.error ?? ""] ?? (res.status === 429 ? ERR.rate_limited : ERR.upstream), "err");
      const r = await decodeSkin(await (await fetch(j.skin)).blob());
      if ("error" in r) return say(r.error, "err");
      replaceSkin(r.pixels, j.model === "slim" ? "slim" : "classic", `Imported ${j.name}'s skin${j.cape ? " and cape" : ""}.`);
      setName(j.name ?? u);
      if (j.cape) {
        const img = await createImageBitmap(await (await fetch(j.cape)).blob());
        const c = document.createElement("canvas");
        c.width = img.width; c.height = img.height;
        c.getContext("2d")!.drawImage(img, 0, 0);
        setCape(c); setCapeRev((n) => n + 1);
      }
    } catch {
      say(ERR.upstream, "err");
    } finally {
      setBusy(false);
    }
  }, [username, replaceSkin, say]);

  const importCape = useCallback(async (f: File) => {
    if (f.size > MAX_SKIN_FILE_BYTES) return say("That cape file is too large.", "err");
    const info = parsePngInfo(new Uint8Array(await f.slice(0, 64).arrayBuffer()));
    if (!info || !((info.width === 64 && info.height === 32) || (info.width === 22 && info.height === 17) || (info.width === 46 && info.height === 22)))
      return say("Capes are 64×32 PNG images.", "err");
    const img = await createImageBitmap(f);
    const c = document.createElement("canvas");
    c.width = img.width; c.height = img.height;
    c.getContext("2d")!.drawImage(img, 0, 0);
    setCape(c); setCapeRev((n) => n + 1);
    say("Cape added to the preview.");
  }, [say]);

  const fileName = () => `${(name.trim() || "my-skin").replace(/[^A-Za-z0-9_-]+/g, "-").slice(0, 40)}.png`;
  const exportBlob = () => canvasBlob(pixelsToCanvas(pix.current));

  const download = async (blob: Blob | null, fname: string) => {
    if (!blob) return say("Couldn't create the image.", "err");
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = fname;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  };

  const copyImage = async () => {
    try {
      const b = await exportBlob();
      if (!b || typeof ClipboardItem === "undefined") throw new Error();
      await navigator.clipboard.write([new ClipboardItem({ "image/png": b })]);
      say("Skin PNG copied to your clipboard.");
    } catch { say("Your browser blocked image copying — use Download instead.", "err"); }
  };

  const copyShare = async () => {
    const b = await exportBlob();
    if (!b) return;
    const enc = toBase64Url(new Uint8Array(await b.arrayBuffer()));
    const url = `${window.location.origin}${window.location.pathname}#skin=${enc}&m=${st.current.model}`;
    try { await navigator.clipboard.writeText(url); say("Share link copied — the skin is inside the link itself, nothing is uploaded."); }
    catch { window.location.hash = `skin=${enc}&m=${st.current.model}`; say("Link is in your address bar — copy it from there."); }
  };

  // drag & drop + paste
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const over = (e: DragEvent) => { if (e.dataTransfer?.types.includes("Files")) { e.preventDefault(); setDragOver(true); } };
    const leave = (e: DragEvent) => { if (e.target === root || !root.contains(e.relatedTarget as Node)) setDragOver(false); };
    const drop = (e: DragEvent) => {
      e.preventDefault(); setDragOver(false);
      const f = e.dataTransfer?.files?.[0];
      if (f) importBlob(f, `Loaded ${f.name}.`);
    };
    const paste = (e: ClipboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && /^(INPUT|TEXTAREA)$/.test(t.tagName)) return;
      const item = [...(e.clipboardData?.items ?? [])].find((i) => i.type === "image/png");
      const f = item?.getAsFile();
      if (f) { e.preventDefault(); importBlob(f, "Pasted skin from your clipboard."); }
    };
    root.addEventListener("dragover", over);
    root.addEventListener("dragleave", leave);
    root.addEventListener("drop", drop);
    window.addEventListener("paste", paste);
    return () => {
      root.removeEventListener("dragover", over); root.removeEventListener("dragleave", leave);
      root.removeEventListener("drop", drop); window.removeEventListener("paste", paste);
    };
  }, [importBlob]);

  // ── 3D picks ────────────────────────────────────────────────────────────
  const onPick = useCallback((p: Pick, phase: "select" | "down" | "move" | "up") => {
    if (phase === "select") { jumpTo(p.part, p.layer, [p.x, p.y]); return; }
    let t = st.current.tool;
    if (t === "line" || t === "rect" || t === "select") t = "pencil";
    if (phase === "down") {
      if (t === "picker") { pickAt(p.x, p.y); return; }
      if (t === "fill") { snapshot(); if (fillAt(p.x, p.y) === 0) undoStack.current.pop(); else commit(); return; }
      snapshot();
      touched.current = new Set();
      stamp(p.x, p.y, t, false);
      commit();
    } else if (phase === "move") {
      if (t === "picker" || t === "fill") return;
      stamp(p.x, p.y, t, false);
      commit();
    } else if (t === "pencil" || t === "noise") pushRecent(st.current.color);
    hover.current = p.x >= 0 ? [p.x, p.y] : null;
    redraw();
  }, [jumpTo, pickAt, fillAt, snapshot, stamp, commit, pushRecent, redraw]);

  // ── keyboard shortcuts ──────────────────────────────────────────────────
  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable)) return;
      const mod = e.ctrlKey || e.metaKey;
      const k = e.key.toLowerCase();
      if (mod && k === "z") { e.preventDefault(); return e.shiftKey ? redo() : undo(); }
      if (mod && k === "y") { e.preventDefault(); return redo(); }
      if (mod && k === "c" && st.current.selection) { e.preventDefault(); return selAction("copy"); }
      if (mod && k === "v" && clip.current) { e.preventDefault(); return selAction("paste"); }
      if (mod || e.altKey) return;
      const tl = TOOLS.find((x) => x.key.toLowerCase() === k);
      if (tl && !(k === "g" && e.shiftKey)) { setTool(tl.id); return; }
      const sel = st.current.selection;
      if (sel && /^arrow/.test(k)) {
        e.preventDefault();
        const dx = k === "arrowleft" ? -1 : k === "arrowright" ? 1 : 0, dy = k === "arrowup" ? -1 : k === "arrowdown" ? 1 : 0;
        snapshot();
        const block = readRegion(pix.current, sel);
        clearRegion(pix.current, sel);
        writeRegion(pix.current, block, sel.x + dx, sel.y + dy, sel.w, sel.h);
        setSelection(clampRect({ ...sel, x: sel.x + dx, y: sel.y + dy }));
        commit();
        return;
      }
      switch (k) {
        case "x": setMirror((m) => !m); break;
        case "[": setSize((s) => Math.max(1, s - 1)); break;
        case "]": setSize((s) => Math.min(4, s + 1)); break;
        case "+": case "=": zoomBy(1); break;
        case "-": zoomBy(-1); break;
        case "0": fitZoom(); break;
        case "1": setLayerMode("both"); break;
        case "2": setLayerMode("base"); break;
        case "3": setLayerMode("overlay"); break;
        case "p": setPaintMode((p) => !p); break;
        case "escape": setSelection(null); break;
        case "delete": case "backspace": if (sel) { e.preventDefault(); selAction("clear"); } break;
        default:
          if (e.key === "G" || (k === "g" && e.shiftKey)) setGrid((g) => !g);
          else if (k === "?") setShowKeys((s) => !s);
      }
    };
    window.addEventListener("keydown", key);
    return () => window.removeEventListener("keydown", key);
  }, [undo, redo, selAction, snapshot, commit, zoomBy, fitZoom]);

  // ── render ──────────────────────────────────────────────────────────────
  const presetThumbs = useMemo(() => SKIN_PRESETS.map((p) => ({ p, pixels: p.draw(p.model) })), []);
  const chip = (on: boolean) => `skc-chip${on ? " on" : ""}`;
  const canUndo = undoStack.current.length > 0, canRedo = redoStack.current.length > 0;
  const colorCss = `rgba(${color[0]},${color[1]},${color[2]},${(layerMode === "base" ? 255 : alpha) / 255})`;
  const swatch = (h: string, label: string) => (
    <button key={label + h} type="button" className={`skc-sw${toHex(color) === h ? " on" : ""}`} style={{ background: h }} title={h} aria-label={`${label} ${h}`}
      onClick={() => chooseColor(parseHex(h)!)} />
  );

  return (
    <div ref={rootRef} className={`skc${dragOver ? " drop" : ""}`} data-skc={variant}>
      <div className="skc-main">
        <section className="skc-col skc-col-view" aria-label="3D preview">
          <SkinViewer3D ref={viewerRef} texture={tex} pixels={pix.current} revision={rev} model={model} cape={cape} capeRevision={capeRev}
            paintMode={paintMode} layerMode={layerMode} onPick={onPick} onPaintModeChange={setPaintMode} />
          <div className="skc-row skc-model" role="group" aria-label="Model">
            <span className="skc-k">Model</span>
            <button type="button" className={chip(model === "classic")} aria-pressed={model === "classic"} onClick={() => setModel("classic")}>Classic · 4px arms</button>
            <button type="button" className={chip(model === "slim")} aria-pressed={model === "slim"} onClick={() => setModel("slim")}>Slim · 3px arms</button>
          </div>
        </section>

        <section className="skc-col skc-col-edit" aria-label="Pixel editor">
          <div className="skc-toolbar" role="toolbar" aria-label="Drawing tools">
            {TOOLS.map((t) => (
              <button key={t.id} type="button" className={`skc-tool${tool === t.id ? " on" : ""}`} onClick={() => setTool(t.id)} aria-pressed={tool === t.id} title={`${t.label} (${t.key})`} aria-label={t.label} data-tool={t.id}>
                <Ico d={t.d} />
              </button>
            ))}
            <span className="skc-sep" aria-hidden="true" />
            <button type="button" className="skc-tool" onClick={undo} disabled={!canUndo} title="Undo (Ctrl+Z)" aria-label="Undo"><Ico d="M9 7 4 12l5 5M4 12h11a5 5 0 0 1 0 10h-2" /></button>
            <button type="button" className="skc-tool" onClick={redo} disabled={!canRedo} title="Redo (Ctrl+Shift+Z)" aria-label="Redo"><Ico d="m15 7 5 5-5 5M20 12H9a5 5 0 0 0 0 10h2" /></button>
          </div>

          <div className="skc-row skc-opts">
            {(tool === "pencil" || tool === "eraser" || tool === "noise" || tool === "shade" || tool === "line") && (
              <div className="skc-seg" role="group" aria-label="Brush size">
                {[1, 2, 3, 4].map((n) => <button key={n} type="button" className={chip(size === n)} aria-pressed={size === n} onClick={() => setSize(n)} title={`Brush ${n}px ([ / ])`}>{n}px</button>)}
              </div>
            )}
            {tool === "rect" && <button type="button" className={chip(rectFill)} aria-pressed={rectFill} onClick={() => setRectFill(!rectFill)}>{rectFill ? "Filled" : "Outline"}</button>}
            <button type="button" className={chip(mirror)} aria-pressed={mirror} onClick={() => setMirror(!mirror)} title="Mirror left ↔ right as you paint (X)">Mirror</button>
            <div className="skc-seg" role="group" aria-label="Editing layer">
              {(["both", "base", "overlay"] as LayerMode[]).map((l, i) => (
                <button key={l} type="button" className={chip(layerMode === l)} aria-pressed={layerMode === l} onClick={() => setLayerMode(l)} title={`${i + 1}`}>
                  {l === "both" ? "Both layers" : l === "base" ? "Base" : "Overlay"}
                </button>
              ))}
            </div>
          </div>

          <div className="skc-row skc-opts">
            <span className="skc-k">Jump to</span>
            {JUMPS.map((j) => <button key={j.part} type="button" className="skc-chip ghost" onClick={() => jumpTo(j.part, layerMode === "overlay" ? "overlay" : "base")}>{j.label}</button>)}
            <span className="skc-grow" />
            <button type="button" className={chip(grid)} aria-pressed={grid} onClick={() => setGrid(!grid)} title="Grid (Shift+G)">Grid</button>
            <button type="button" className={chip(guides)} aria-pressed={guides} onClick={() => setGuides(!guides)}>Guides</button>
            <div className="skc-seg" role="group" aria-label="Zoom">
              <button type="button" className="skc-chip" onClick={() => zoomBy(-1)} aria-label="Zoom out">−</button>
              <button type="button" className="skc-chip" onClick={fitZoom} title="Fit (0)">Fit</button>
              <button type="button" className="skc-chip" onClick={() => zoomBy(1)} aria-label="Zoom in">+</button>
            </div>
          </div>

          {selection && (
            <div className="skc-row skc-selbar" role="group" aria-label="Selection">
              <span className="skc-k">{selection.w}×{selection.h}</span>
              <button type="button" className="skc-chip" onClick={() => selAction("flipH")}>Flip ↔</button>
              <button type="button" className="skc-chip" onClick={() => selAction("flipV")}>Flip ↕</button>
              <button type="button" className="skc-chip" onClick={() => selAction("rotCCW")} disabled={selection.w !== selection.h}>Rotate ⟲</button>
              <button type="button" className="skc-chip" onClick={() => selAction("rotCW")} disabled={selection.w !== selection.h}>Rotate ⟳</button>
              <button type="button" className="skc-chip" onClick={() => selAction("mirrorCopy")} title="Copy this area onto the opposite limb / side">Copy to other side</button>
              <button type="button" className="skc-chip" onClick={() => selAction("copy")}>Copy</button>
              <button type="button" className="skc-chip" onClick={() => selAction("clear")}>Clear</button>
              <button type="button" className="skc-chip ghost" onClick={() => setSelection(null)}>Done</button>
            </div>
          )}

          <div ref={wrapRef} className="skc-canvas-wrap">
            <canvas ref={canvasRef} className="skc-canvas" data-tool={tool} style={{ width: SKIN_SIZE * zoom, height: SKIN_SIZE * zoom }}
              onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onPointerLeave={onLeave}
              onContextMenu={(e) => e.preventDefault()} role="img" aria-label="64 by 64 skin texture editor" />
          </div>
          {translucent > 0 && (
            <p className="skc-warn">{translucent} base-layer texel{translucent === 1 ? " is" : "s are"} transparent — Minecraft shows those as solid black. Paint them, or keep see-through details on the overlay layer.</p>
          )}

          <div className="skc-colors">
            <div className="skc-current">
              <span className="skc-big" style={{ background: colorCss }} aria-hidden="true" />
              <label className="skc-native" title="Pick any colour">
                <input type="color" value={toHex(color)} onChange={(e) => chooseColor(parseHex(e.target.value)!)} aria-label="Colour picker" />
              </label>
              <input className="skc-hex" value={hexDraft} spellCheck={false} maxLength={9} aria-label="Hex colour"
                onChange={(e) => { setHexDraft(e.target.value); const c = parseHex(e.target.value); if (c) { setColor([c[0], c[1], c[2], 255]); if (c[3] !== 255) setAlpha(c[3]); } }}
                onBlur={() => setHexDraft(toHex(color))} />
              <label className="skc-range skc-alpha" title="Overlay opacity (base layer is always opaque)">
                <span>Overlay opacity</span>
                <input type="range" min={16} max={255} step={1} value={alpha} onChange={(e) => setAlpha(Number(e.target.value))} aria-label="Overlay paint opacity" />
              </label>
            </div>
            <div className="skc-pal" aria-label="Palette">{PALETTE.map((h) => swatch(h, "Palette"))}</div>
            {recent.length > 0 && <div className="skc-pal"><span className="skc-k">Recent</span>{recent.map((h) => swatch(h, "Recent"))}</div>}
            {inUse.length > 0 && <div className="skc-pal"><span className="skc-k">In this skin</span>{inUse.map((h) => swatch(h, "In use"))}</div>}
          </div>
        </section>
      </div>

      <div className="skc-panels">
        <section className="skc-panel" aria-labelledby="skc-imp">
          <h3 id="skc-imp">Import</h3>
          <form className="skc-imp" onSubmit={(e) => { e.preventDefault(); importUsername(); }}>
            <input className="skc-text" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="Minecraft username" maxLength={16}
              aria-label="Minecraft Java username" autoComplete="off" spellCheck={false} />
            <button type="submit" className="skc-btn" disabled={busy}>{busy ? "Fetching…" : "Get skin"}</button>
          </form>
          <p className="skc-note">Loads any Java player&apos;s current skin (and cape) so you can remix it.</p>
          <div className="skc-row">
            <button type="button" className="skc-btn ghost" onClick={() => fileRef.current?.click()}>Upload PNG</button>
            <button type="button" className="skc-btn ghost" onClick={() => capeFileRef.current?.click()}>Add a cape</button>
            {cape && <button type="button" className="skc-chip ghost" onClick={() => { setCape(null); setCapeRev((n) => n + 1); }}>Remove cape</button>}
          </div>
          <p className="skc-note">Or drop a skin file anywhere on the editor, or paste one (Ctrl+V). 64×64 and old 64×32 skins both work.</p>
          <input ref={fileRef} type="file" accept="image/png" hidden onChange={(e) => { const f = e.target.files?.[0]; if (f) importBlob(f, `Loaded ${f.name}.`); e.target.value = ""; }} />
          <input ref={capeFileRef} type="file" accept="image/png" hidden onChange={(e) => { const f = e.target.files?.[0]; if (f) importCape(f); e.target.value = ""; }} />
        </section>

        <section className="skc-panel" aria-labelledby="skc-tpl">
          <h3 id="skc-tpl">Start from a template</h3>
          <div className="skc-tpls">
            {presetThumbs.map(({ p, pixels }) => (
              <button key={p.id} type="button" className="skc-tpl" title={p.blurb} onClick={() => replaceSkin(p.draw(p.model), p.model, `Loaded the ${p.name} template.`)}>
                <Thumb pixels={pixels} model={p.model} />
                <span>{p.name}</span>
              </button>
            ))}
          </div>
          <div className="skc-row">
            <button type="button" className="skc-chip ghost" onClick={() => replaceSkin(blankPixels(), st.current.model, "Cleared — a fully transparent canvas.")}>Blank canvas</button>
          </div>
        </section>

        <section className="skc-panel" aria-labelledby="skc-exp">
          <h3 id="skc-exp">Export</h3>
          <label className="skc-field"><span>File name</span>
            <input className="skc-text" value={name} onChange={(e) => setName(e.target.value)} maxLength={40} aria-label="File name" spellCheck={false} />
          </label>
          <div className="skc-row">
            <button type="button" className="skc-btn" onClick={async () => download(await exportBlob(), fileName())} data-action="download">Download skin PNG</button>
            <button type="button" className="skc-btn ghost" onClick={copyImage}>Copy image</button>
          </div>
          <div className="skc-row">
            <button type="button" className="skc-btn ghost" onClick={copyShare}>Copy share link</button>
            <button type="button" className="skc-btn ghost" onClick={async () => download(await viewerRef.current?.screenshot() ?? null, fileName().replace(/\.png$/, "-3d.png"))}>3D screenshot</button>
          </div>
          <p className="skc-note">Choose <b>{model === "slim" ? "Slim (Alex)" : "Classic (Steve)"}</b> when you upload it in Minecraft — the model isn&apos;t stored in the PNG.</p>
        </section>
      </div>

      <details className="skc-howto">
        <summary>How to put this skin on your Minecraft character</summary>
        <div className="skc-howto-cols">
          <div>
            <h4>Java Edition</h4>
            <ol>
              <li>Download your skin PNG above.</li>
              <li>Open the Minecraft Launcher and pick <b>Minecraft: Java Edition</b>.</li>
              <li>Go to the <b>Skins</b> tab and choose <b>New skin</b>.</li>
              <li>Browse to the PNG, pick <b>{model === "slim" ? "Slim" : "Classic"}</b> as the player model, then <b>Save &amp; Use</b>.</li>
              <li>Rejoin your world or server — everyone sees the new skin.</li>
            </ol>
          </div>
          <div>
            <h4>Bedrock Edition</h4>
            <ol>
              <li>Get the PNG onto the device you play on.</li>
              <li>From the main menu open the <b>Dressing Room</b>.</li>
              <li>Open <b>Classic Skins</b>, select <b>Owned</b>, then <b>Import</b> → <b>Choose New Skin</b>.</li>
              <li>Pick the PNG and the matching arm width ({model === "slim" ? "slim" : "wide"}).</li>
            </ol>
          </div>
        </div>
      </details>

      <div className="skc-foot">
        <button type="button" className="skc-chip ghost" onClick={() => setShowKeys(!showKeys)} aria-expanded={showKeys}>Keyboard shortcuts</button>
        <span className="skc-note">Runs entirely in your browser · your skin never leaves your device unless you share it</span>
      </div>
      {showKeys && (
        <div className="skc-keys">
          {TOOLS.map((t) => <span key={t.id}><kbd>{t.key}</kbd>{t.label}</span>)}
          <span><kbd>Alt</kbd>+click pick colour</span><span><kbd>X</kbd>mirror</span><span><kbd>[</kbd><kbd>]</kbd>brush size</span>
          <span><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd>layer</span><span><kbd>P</kbd>paint on model</span><span><kbd>Shift</kbd>+<kbd>G</kbd>grid</span>
          <span><kbd>Ctrl</kbd>+<kbd>Z</kbd>undo</span><span><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd>redo</span>
          <span><kbd>Ctrl</kbd>+<kbd>C</kbd>/<kbd>V</kbd>copy/paste area</span><span><kbd>←↑→↓</kbd>nudge selection</span>
          <span><kbd>Del</kbd>clear selection</span><span><kbd>+</kbd><kbd>−</kbd><kbd>0</kbd>zoom</span>
        </div>
      )}
      {dragOver && <div className="skc-dropzone" aria-hidden="true">Drop a skin PNG to load it</div>}
      <div className={`skc-toast${toast ? " show" : ""}${toast?.tone === "err" ? " err" : ""}`} role="status" aria-live="polite">{toast?.msg}</div>
    </div>
  );
}

export default SkinCreator;

// exported for the page-level JSON-LD / docs: the tool's real feature list
export const SKIN_CREATOR_FEATURES = [
  "Animated 3D preview (idle, walk, run, fly, wave, crouch, hit, swim)",
  "Classic (Steve) and slim (Alex) models",
  "Paint on the 2D texture or directly on the 3D model",
  "Base and overlay layers (hat, jacket, sleeves, pants)",
  "Mirror painting, undo/redo, select, move, flip and rotate",
  "Import by Minecraft username, PNG upload, drag & drop or paste",
  "Download PNG, copy image, share link, 3D screenshot",
];
void faceRects;

