input.content:
/*
 * Minecraft skin creator — one stylesheet, two themes.
 * Every rule is under `.skc[data-skc]` (a class only this component renders),
 * so nothing here can reach any other page or the shared component classes.
 * The doubled `[data-skc]` prefix also out-ranks the marketing tool panel's
 * `.tt-app :is(input…)` restyling (app/nxm/_pages/tools-tool/page.css),
 * which was written for single-field tools and would stretch these controls.
 *
 * Themes are only custom properties:
 *   data-skc="nxm"     the new marketing site (Aurora: navy glass, violet→blue)
 *   data-skc="nexion"  the customer portal — mapped onto the portal's own
 *                      --color-* tokens, so its light mode flips this too.
 */
.skc[data-skc] {
  --skc-text: #eef2ff;
  --skc-mute: #9ca6cc;
  --skc-faint: #6f7aa3;
  --skc-surface: rgba(10, 15, 38, 0.72);
  --skc-surface-2: rgba(16, 22, 52, 0.9);
  --skc-well: #070b1d;
  --skc-line: rgba(150, 160, 255, 0.16);
  --skc-line-2: rgba(150, 160, 255, 0.3);
  --skc-accent: #7b3fef;
  --skc-accent-2: #3b6be8;
  --skc-cyan: #3edcf2;
  --skc-grad: linear-gradient(120deg, #3b6be8, #7b3fef);
  --skc-on-accent: #fff;
  --skc-radius: 16px;
  --skc-font: inherit;
  --skc-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --skc-check-a: #1a2042;
  --skc-check-b: #131834;
  --skc-unused: rgba(3, 5, 16, 0.78);
  --skc-guide-base: rgba(110, 160, 255, 0.6);
  --skc-guide-overlay: rgba(200, 140, 255, 0.6);
  --skc-gridline: rgba(255, 255, 255, 0.09);
  --skc-label: rgba(225, 232, 255, 0.9);
  --skc-sel: #3edcf2;
  --skc-hover: #ffffff;
  --skc-focus: #3edcf2;
  --skc-stage: radial-gradient(120% 90% at 50% 0%, rgba(123, 63, 239, 0.22), transparent 60%), radial-gradient(80% 60% at 50% 100%, rgba(59, 107, 232, 0.18), transparent 70%), #080c22;

  position: relative;
  display: flex;
  flex-direction: column;
  gap: 18px;
  color: var(--skc-text);
  font-family: var(--skc-font);
  font-size: 14px;
  line-height: 1.45;
  -webkit-tap-highlight-color: transparent;
}
.skc[data-skc="nxm"] {
  --skc-text: var(--ink, #eef2ff);
  --skc-mute: var(--muted, #9ca6cc);
  --skc-line: var(--au-line, rgba(150, 160, 255, 0.16));
  --skc-line-2: var(--au-line-2, rgba(150, 160, 255, 0.3));
  --skc-grad: var(--au-grad, linear-gradient(120deg, #3b6be8, #7b3fef));
  --skc-font: var(--f-body, inherit);
  --skc-mono: var(--f-mono, ui-monospace, monospace);
}
.skc[data-skc="nexion"] {
  --skc-text: var(--color-tx, #fff);
  --skc-mute: var(--color-tx-mute, #93aede);
  --skc-faint: var(--color-tx-faint, #5f7cb4);
  --skc-surface: var(--color-well, #000c1e);
  --skc-surface-2: var(--color-hover, #021428);
  --skc-well: var(--color-void, #00060f);
  --skc-line: var(--color-rim-soft, #00173b);
  --skc-line-2: var(--color-rim-hi, #002a5e);
  --skc-accent: var(--color-violet, #8c3ae9);
  --skc-accent-2: var(--color-blue, #2f7eef);
  --skc-cyan: var(--color-cyan, #14c5e4);
  --skc-grad: linear-gradient(120deg, var(--color-blue, #2f7eef), var(--color-violet, #8c3ae9));
  --skc-radius: var(--radius-card, 12px);
  --skc-sel: var(--color-cyan, #14c5e4);
  --skc-focus: var(--color-cyan, #14c5e4);
}
/* portal light mode: the editor's checkerboard + chrome go light too (the 3D stage stays dark for contrast) */
:root[data-theme="light"] .skc[data-skc="nexion"] {
  --skc-check-a: #e6ebf4;
  --skc-check-b: #d5dce9;
  --skc-unused: rgba(160, 172, 196, 0.55);
  --skc-guide-base: rgba(47, 126, 239, 0.75);
  --skc-guide-overlay: rgba(140, 58, 233, 0.75);
  --skc-gridline: rgba(10, 30, 70, 0.12);
  --skc-label: rgba(10, 24, 50, 0.85);
  --skc-hover: #081729;
}

.skc[data-skc] *,
.skc[data-skc] *::before,
.skc[data-skc] *::after { box-sizing: border-box; }
.skc[data-skc] svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.skc[data-skc] .skc-main { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
@media (min-width: 900px) { .skc[data-skc] .skc-main { grid-template-columns: minmax(280px, 0.82fr) minmax(0, 1.18fr); align-items: start; } }
.skc[data-skc] .skc-col { display: flex; flex-direction: column; gap: 10px; min-width: 0; }

/* ── 3D stage ─────────────────────────────────────────────────────────── */
.skc[data-skc] .skc-viewer { display: flex; flex-direction: column; gap: 10px; }
.skc[data-skc] .skc-stage {
  position: relative; height: clamp(320px, 52vh, 480px); border-radius: var(--skc-radius); overflow: hidden;
  background: var(--skc-stage); border: 1px solid var(--skc-line); touch-action: none; cursor: grab;
}
.skc[data-skc] .skc-stage:active { cursor: grabbing; }
.skc[data-skc] .skc-stage[data-bg="studio"] { background: #e7ebf4; }
.skc[data-skc] .skc-stage.painting { box-shadow: inset 0 0 0 2px var(--skc-cyan); }
.skc[data-skc] .skc-3d { display: block; width: 100%; height: 100%; }
.skc[data-skc] .skc-stage-msg { position: absolute; inset: 0; display: grid; place-items: center; align-content: center; gap: 10px; color: var(--skc-mute); font-size: 13px; }
.skc[data-skc] .skc-spin { width: 26px; height: 26px; border-radius: 50%; border: 3px solid var(--skc-line-2); border-top-color: var(--skc-cyan); animation: skc-spin 0.8s linear infinite; }
.skc[data-skc] .skc-stage-fallback { position: absolute; inset: 0; display: grid; place-items: center; align-content: center; gap: 12px; padding: 16px; text-align: center; color: var(--skc-mute); font-size: 13px; }
.skc[data-skc] .skc-flat { image-rendering: pixelated; }
.skc[data-skc] .skc-stage-tools { position: absolute; left: 10px; right: 10px; top: 10px; display: flex; gap: 6px; flex-wrap: wrap; pointer-events: none; }
.skc[data-skc] .skc-stage-tools > * { pointer-events: auto; backdrop-filter: blur(6px); }
.skc[data-skc] .skc-vctl { display: flex; flex-direction: column; gap: 8px; }

/* ── shared controls ──────────────────────────────────────────────────── */
.skc[data-skc] .skc-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.skc[data-skc] .skc-grow { flex: 1; }
.skc[data-skc] .skc-k { font: 600 10.5px var(--skc-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--skc-mute); margin-right: 2px; }
.skc[data-skc] .skc-seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 11px; background: var(--skc-surface); border: 1px solid var(--skc-line); }
.skc[data-skc] .skc-seg .skc-chip { border-color: transparent; background: transparent; }
.skc[data-skc] .skc-seg .skc-chip.on { background: var(--skc-grad); }
.skc[data-skc] .skc-chip {
  display: inline-flex; align-items: center; gap: 6px; min-height: 30px; padding: 0 11px; border-radius: 9px;
  border: 1px solid var(--skc-line); background: var(--skc-surface); color: var(--skc-text);
  font: 600 12.5px var(--skc-font); cursor: pointer; white-space: nowrap; transition: background-color 0.15s, border-color 0.15s, box-shadow 0.15s;
}
.skc[data-skc] .skc-chip svg { width: 15px; height: 15px; }
.skc[data-skc] .skc-chip:hover { border-color: var(--skc-line-2); background: var(--skc-surface-2); }
.skc[data-skc] .skc-chip.on { background: var(--skc-grad); border-color: transparent; color: var(--skc-on-accent); box-shadow: 0 6px 18px -10px var(--skc-accent); }
.skc[data-skc] .skc-chip.ghost { background: transparent; }
.skc[data-skc] .skc-chip:disabled { opacity: 0.4; cursor: not-allowed; }
.skc[data-skc] .skc-chip:focus-visible, .skc[data-skc] .skc-tool:focus-visible, .skc[data-skc] .skc-btn:focus-visible, .skc[data-skc] .skc-sw:focus-visible, .skc[data-skc] .skc-tpl:focus-visible { outline: 2px solid var(--skc-cyan); outline-offset: 2px; }

.skc[data-skc] .skc-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; padding: 0 16px; border-radius: 12px; border: 0;
  background: var(--skc-grad); color: var(--skc-on-accent); font: 700 13.5px var(--skc-font); cursor: pointer; white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3), 0 10px 26px -14px var(--skc-accent);
}
.skc[data-skc] .skc-btn:hover { filter: brightness(1.08); }
.skc[data-skc] .skc-btn:disabled { opacity: 0.6; cursor: progress; }
.skc[data-skc] .skc-btn.ghost { background: var(--skc-surface); color: var(--skc-text); border: 1px solid var(--skc-line-2); box-shadow: none; }
.skc[data-skc] .skc-btn.ghost:hover { background: var(--skc-surface-2); }

.skc[data-skc] input.skc-text, .skc[data-skc] input.skc-hex {
  width: 100%; min-width: 0; min-height: 40px; height: 40px; padding: 0 12px; border-radius: 11px; border: 1px solid var(--skc-line-2);
  background: var(--skc-well); color: var(--skc-text); font: 600 13.5px var(--skc-font); box-shadow: none; outline: none;
}
.skc[data-skc] input.skc-hex { width: 104px; font-family: var(--skc-mono); text-transform: lowercase; }
.skc[data-skc] input.skc-text:focus, .skc[data-skc] input.skc-hex:focus { border-color: var(--skc-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--skc-accent) 25%, transparent); }
.skc[data-skc] .skc-range { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--skc-mute); }
.skc[data-skc] .skc-range input[type="range"] {
  -webkit-appearance: none; appearance: none; width: 110px; height: 20px; min-height: 0; padding: 0; margin: 0; border: 0; background: transparent; box-shadow: none; accent-color: var(--skc-accent);
}
.skc[data-skc] .skc-range input[type="range"]::-webkit-slider-runnable-track { height: 6px; border-radius: 6px; background: var(--skc-grad); }
.skc[data-skc] .skc-range input[type="range"]::-moz-range-track { height: 6px; border-radius: 6px; background: var(--skc-grad); }
.skc[data-skc] .skc-range input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; margin-top: -5px; border-radius: 50%; background: #fff; border: 0; box-shadow: 0 0 0 3px var(--skc-accent); }
.skc[data-skc] .skc-range input[type="range"]::-moz-range-thumb { width: 16px; height: 16px; border-radius: 50%; background: #fff; border: 0; box-shadow: 0 0 0 3px var(--skc-accent); }

/* ── editor ───────────────────────────────────────────────────────────── */
.skc[data-skc] .skc-toolbar { display: flex; flex-wrap: wrap; gap: 4px; padding: 5px; border-radius: 14px; background: var(--skc-surface); border: 1px solid var(--skc-line); }
.skc[data-skc] .skc-tool {
  display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; border: 0; background: transparent; color: var(--skc-text); cursor: pointer;
  transition: background-color 0.15s;
}
.skc[data-skc] .skc-tool:hover { background: var(--skc-surface-2); }
.skc[data-skc] .skc-tool.on { background: var(--skc-grad); color: var(--skc-on-accent); box-shadow: 0 8px 20px -12px var(--skc-accent); }
.skc[data-skc] .skc-tool:disabled { opacity: 0.35; cursor: not-allowed; }
.skc[data-skc] .skc-sep { width: 1px; align-self: stretch; margin: 4px 3px; background: var(--skc-line-2); }
.skc[data-skc] .skc-opts { row-gap: 8px; }
.skc[data-skc] .skc-selbar { padding: 6px 8px; border-radius: 12px; border: 1px dashed color-mix(in srgb, var(--skc-cyan) 55%, transparent); background: color-mix(in srgb, var(--skc-cyan) 7%, transparent); }

.skc[data-skc] .skc-canvas-wrap {
  position: relative; max-height: min(70vh, 640px); overflow: auto; border-radius: var(--skc-radius); border: 1px solid var(--skc-line); background: var(--skc-well);
  overscroll-behavior: contain; scrollbar-width: thin;
}
.skc[data-skc] .skc-canvas { display: block; touch-action: none; image-rendering: pixelated; cursor: crosshair; }
.skc[data-skc] .skc-canvas[data-tool="select"] { cursor: cell; }
.skc[data-skc] .skc-canvas[data-tool="picker"] { cursor: copy; }
.skc[data-skc] .skc-warn { margin: 0; padding: 8px 12px; border-radius: 10px; font-size: 12.5px; color: #ffd28a; background: rgba(239, 168, 40, 0.1); border: 1px solid rgba(239, 168, 40, 0.3); }
:root[data-theme="light"] .skc[data-skc="nexion"] .skc-warn { color: #8a5300; }

.skc[data-skc] .skc-colors { display: flex; flex-direction: column; gap: 8px; padding: 10px; border-radius: 14px; background: var(--skc-surface); border: 1px solid var(--skc-line); }
.skc[data-skc] .skc-current { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.skc[data-skc] .skc-big { width: 40px; height: 40px; border-radius: 11px; border: 1px solid var(--skc-line-2); background-clip: padding-box;
  box-shadow: inset 0 0 0 999px transparent; background-image: linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%), linear-gradient(45deg, #888 25%, #bbb 25%, #bbb 75%, #888 75%); }
.skc[data-skc] .skc-native { position: relative; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 11px; overflow: hidden; border: 1px solid var(--skc-line-2); background: conic-gradient(from 0deg, #f33, #fd3, #3f6, #3df, #36f, #c3f, #f33); cursor: pointer; }
.skc[data-skc] .skc-native input[type="color"] { position: absolute; inset: 0; width: 100%; height: 100%; min-height: 0; padding: 0; border: 0; opacity: 0; cursor: pointer; }
.skc[data-skc] .skc-pal { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; }
.skc[data-skc] .skc-sw { width: 24px; height: 24px; padding: 0; border-radius: 7px; border: 1px solid rgba(255, 255, 255, 0.14); cursor: pointer; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.25); }
.skc[data-skc] .skc-sw.on { outline: 2px solid var(--skc-cyan); outline-offset: 1px; }
.skc[data-skc] .skc-sw:hover { transform: translateY(-1px); }

/* ── panels ───────────────────────────────────────────────────────────── */
.skc[data-skc] .skc-panels { display: grid; gap: 14px; grid-template-columns: minmax(0, 1fr); }
@media (min-width: 900px) { .skc[data-skc] .skc-panels { grid-template-columns: 1fr 1.25fr 1fr; } }
.skc[data-skc] .skc-panel { display: flex; flex-direction: column; gap: 10px; padding: 16px; border-radius: var(--skc-radius); background: var(--skc-surface); border: 1px solid var(--skc-line); min-width: 0; }
.skc[data-skc] .skc-panel h3 { margin: 0; font: 700 14.5px var(--skc-font); color: var(--skc-text); letter-spacing: -0.01em; }
.skc[data-skc] .skc-imp { display: flex; gap: 6px; }
.skc[data-skc] .skc-note { margin: 0; font-size: 12px; color: var(--skc-mute); }
.skc[data-skc] .skc-note b { color: var(--skc-text); }
.skc[data-skc] .skc-field { display: flex; flex-direction: column; gap: 5px; font-size: 12px; color: var(--skc-mute); }
.skc[data-skc] .skc-tpls { display: grid; grid-template-columns: repeat(auto-fill, minmax(76px, 1fr)); gap: 6px; }
.skc[data-skc] .skc-tpl { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 8px 4px 6px; border-radius: 12px; border: 1px solid var(--skc-line); background: var(--skc-well); color: var(--skc-text); cursor: pointer; font: 600 11px var(--skc-font); text-align: center; }
.skc[data-skc] .skc-tpl:hover { border-color: var(--skc-accent); }
.skc[data-skc] .skc-thumb { width: 36px; height: 72px; image-rendering: pixelated; }

.skc[data-skc] .skc-howto { border-radius: var(--skc-radius); background: var(--skc-surface); border: 1px solid var(--skc-line); padding: 0 16px; }
.skc[data-skc] .skc-howto summary { cursor: pointer; padding: 14px 0; font-weight: 700; list-style: none; }
.skc[data-skc] .skc-howto summary::-webkit-details-marker { display: none; }
.skc[data-skc] .skc-howto summary::after { content: "+"; float: right; color: var(--skc-mute); }
.skc[data-skc] .skc-howto[open] summary::after { content: "–"; }
.skc[data-skc] .skc-howto-cols { display: grid; gap: 16px; padding-bottom: 16px; grid-template-columns: minmax(0, 1fr); }
@media (min-width: 700px) { .skc[data-skc] .skc-howto-cols { grid-template-columns: 1fr 1fr; } }
.skc[data-skc] .skc-howto h4 { margin: 0 0 6px; font-size: 13px; color: var(--skc-text); }
.skc[data-skc] .skc-howto ol { margin: 0; padding-left: 18px; color: var(--skc-mute); font-size: 13px; display: grid; gap: 4px; }
.skc[data-skc] .skc-howto b { color: var(--skc-text); }

.skc[data-skc] .skc-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.skc[data-skc] .skc-keys { display: flex; flex-wrap: wrap; gap: 6px 14px; padding: 12px 14px; border-radius: 12px; background: var(--skc-surface); border: 1px solid var(--skc-line); font-size: 12px; color: var(--skc-mute); }
.skc[data-skc] kbd { display: inline-block; min-width: 20px; margin-right: 5px; padding: 1px 5px; border-radius: 5px; border: 1px solid var(--skc-line-2); background: var(--skc-well); color: var(--skc-text); font: 600 11px var(--skc-mono); text-align: center; }

.skc[data-skc] .skc-dropzone { position: absolute; inset: -6px; z-index: 5; display: grid; place-items: center; border-radius: calc(var(--skc-radius) + 6px); border: 2px dashed var(--skc-cyan); background: color-mix(in srgb, var(--skc-well) 80%, transparent); font: 700 16px var(--skc-font); color: var(--skc-text); pointer-events: none; }
.skc[data-skc] .skc-toast {
  position: fixed; left: 50%; bottom: 22px; z-index: 60; max-width: min(92vw, 520px); padding: 10px 16px; border-radius: 12px; transform: translate(-50%, 20px); opacity: 0; pointer-events: none;
  background: #0d1433; color: #eef2ff; border: 1px solid rgba(62, 220, 242, 0.45); box-shadow: 0 16px 40px -16px rgba(0, 0, 0, 0.7); font-size: 13px; transition: opacity 0.2s, transform 0.2s;
}
.skc[data-skc] .skc-toast.show { opacity: 1; transform: translate(-50%, 0); }
.skc[data-skc] .skc-toast.err { border-color: rgba(239, 66, 108, 0.6); }

.skc-loading { display: grid; place-items: center; min-height: 420px; color: #9ca6cc; font-size: 14px; }

@media (max-width: 640px) {
  .skc[data-skc] { gap: 14px; }
  .skc[data-skc] .skc-stage { height: 320px; }
  .skc[data-skc] .skc-tool { width: 36px; height: 36px; }
  .skc[data-skc] .skc-panel { padding: 14px; }
}
@media (prefers-reduced-motion: reduce) { .skc[data-skc] * { transition: none !important; } }

@keyframes skc-spin { to { transform: rotate(360deg); } }

toolu_01UTPC2eT8fBzmgX2S2bVYfZ.content:
/*
 * Minecraft skin creator — one stylesheet, two themes.
 * Every rule is under `.skc[data-skc]` (a class only this component renders),
 * so nothing here can reach any other page or the shared component classes.
 * The doubled `[data-skc]` prefix also out-ranks the marketing tool panel's
 * `.tt-app :is(input…)` restyling (app/nxm/_pages/tools-tool/page.css),
 * which was written for single-field tools and would stretch these controls.
 *
 * Themes are only custom properties:
 *   data-skc="nxm"     the new marketing site (Aurora: navy glass, violet→blue)
 *   data-skc="nexion"  the customer portal — mapped onto the portal's own
 *                      --color-* tokens, so its light mode flips this too.
 */
.skc[data-skc] {
  --skc-text: #eef2ff;
  --skc-mute: #9ca6cc;
  --skc-faint: #6f7aa3;
  --skc-surface: rgba(10, 15, 38, 0.72);
  --skc-surface-2: rgba(16, 22, 52, 0.9);
  --skc-well: #070b1d;
  --skc-line: rgba(150, 160, 255, 0.16);
  --skc-line-2: rgba(150, 160, 255, 0.3);
  --skc-accent: #7b3fef;
  --skc-accent-2: #3b6be8;
  --skc-cyan: #3edcf2;
  --skc-grad: linear-gradient(120deg, #3b6be8, #7b3fef);
  --skc-on-accent: #fff;
  --skc-radius: 16px;
  --skc-font: inherit;
  --skc-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --skc-check-a: #1a2042;
  --skc-check-b: #131834;
  --skc-unused: rgba(3, 5, 16, 0.78);
  --skc-guide-base: rgba(110, 160, 255, 0.6);
  --skc-guide-overlay: rgba(200, 140, 255, 0.6);
  --skc-gridline: rgba(255, 255, 255, 0.09);
  --skc-label: rgba(225, 232, 255, 0.9);
  --skc-sel: #3edcf2;
  --skc-hover: #ffffff;
  --skc-focus: #3edcf2;
  --skc-stage: radial-gradient(120% 90% at 50% 0%, rgba(123, 63, 239, 0.22), transparent 60%), radial-gradient(80% 60% at 50% 100%, rgba(59, 107, 232, 0.18), transparent 70%), #080c22;

  position: relative;
  display: flex;
  flex-direction: column;
  gap: 18px;
  color: var(--skc-text);
  font-family: var(--skc-font);
  font-size: 14px;
  line-height: 1.45;
  -webkit-tap-highlight-color: transparent;
}
.skc[data-skc="nxm"] {
  --skc-text: var(--ink, #eef2ff);
  --skc-mute: var(--muted, #9ca6cc);
  --skc-line: var(--au-line, rgba(150, 160, 255, 0.16));
  --skc-line-2: var(--au-line-2, rgba(150, 160, 255, 0.3));
  --skc-grad: var(--au-grad, linear-gradient(120deg, #3b6be8, #7b3fef));
  --skc-font: var(--f-body, inherit);
  --skc-mono: var(--f-mono, ui-monospace, monospace);
}
.skc[data-skc="nexion"] {
  --skc-text: var(--color-tx, #fff);
  --skc-mute: var(--color-tx-mute, #93aede);
  --skc-faint: var(--color-tx-faint, #5f7cb4);
  --skc-surface: var(--color-well, #000c1e);
  --skc-surface-2: var(--color-hover, #021428);
  --skc-well: var(--color-void, #00060f);
  --skc-line: var(--color-rim-soft, #00173b);
  --skc-line-2: var(--color-rim-hi, #002a5e);
  --skc-accent: var(--color-violet, #8c3ae9);
  --skc-accent-2: var(--color-blue, #2f7eef);
  --skc-cyan: var(--color-cyan, #14c5e4);
