import type { Metadata } from "next";
import Link from "next/link";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { SkinCreatorLazy } from "@/components/skin-creator/SkinCreatorLazy";
import { relatedTools } from "@/lib/tools/catalog";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

/*
 * The Minecraft skin creator's page. This file is ALSO the content source for
 * the new marketing site's /tools/minecraft-skin-creator (app/nxm/_data/
 * tools-live.ts reads the ToolShell props below: copy, FAQ, steps, related
 * tools, the extra JSON-LD, the CTA and the fact chips) — edit the copy here.
 * Vetting notes + attributions: docs/TOOL-SKIN-CREATOR.md.
 */
export const metadata: Metadata = {
  title: "Minecraft Skin Creator — Free 3D Skin Editor & Maker",
  description:
    "Free Minecraft skin creator with an animated 3D preview. Paint pixel by pixel or right on the model, import any player's skin by username, use Steve or Alex arms, then download the PNG for Java or Bedrock.",
  alternates: { canonical: "/tools/minecraft-skin-creator" },
};

const faq: ToolFaq[] = [
  {
    q: "Is this Minecraft skin creator free?",
    a: "Yes. It's completely free, needs no account and adds no watermark. Painting, templates, upload and download all run in your browser; only 'Import by username' asks our server to fetch that player's public skin from Minecraft.",
  },
  {
    q: "What size is a Minecraft skin?",
    a: "A modern skin is a 64×64 pixel PNG. Older skins from before Minecraft 1.8 are 64×32 — you can upload those too and the editor converts them to 64×64 automatically, mirroring the right arm and leg onto the left the same way the game does.",
  },
  {
    q: "What's the difference between Classic (Steve) and Slim (Alex)?",
    a: "Classic skins have 4-pixel-wide arms, Slim skins have 3-pixel-wide arms. The texture layout is the same apart from the arms. The PNG doesn't record which model you chose, so pick the same one when you upload the skin in Minecraft.",
  },
  {
    q: "What are the base and overlay layers?",
    a: "Every body part has two layers. The base layer is the body itself and is always solid. The overlay (hat, jacket, sleeves and pants) floats slightly outside it and can be transparent, which is how skins get 3D-looking hair, hoods, glasses and armour.",
  },
  {
    q: "Can I edit an existing skin or someone else's skin?",
    a: "Yes. Type any Minecraft Java username to load that player's current skin (and cape), or upload a PNG, drop it onto the editor, or paste it from your clipboard. Then remix every pixel.",
  },
  {
    q: "Does it work for both Java and Bedrock Edition?",
    a: "Yes. Both editions use the same 64×64 PNG format. The guide under the editor walks through applying it in the Java launcher and in Bedrock's Dressing Room.",
  },
  {
    q: "Can I paint directly on the 3D model?",
    a: "Yes. Turn on 'Paint on model' and draw on the 3D character with the pencil, eraser, fill, texture brush or eyedropper. With it off, clicking a body part jumps the 2D editor to that part.",
  },
  {
    q: "Does it work on a phone or tablet?",
    a: "Yes. The editor supports touch: paint with one finger and pinch with two to zoom the canvas. The 3D preview rotates with a drag and zooms with a pinch.",
  },
  {
    q: "Can my players use custom skins on my own server?",
    a: "Yes. Skins are tied to the player's Minecraft account, not to the server, so anyone who uploads a skin sees it on every server they join — including your own Nxeon Minecraft server.",
  },
];

const steps = [
  "Start from a template, a blank canvas, an uploaded PNG, or import a player's skin by username.",
  "Pick Classic (4px arms) or Slim (3px arms) to match the model you'll use in Minecraft.",
  "Paint on the 2D texture or straight onto the 3D model — use mirror mode to paint both sides at once.",
  "Switch between the base and overlay layers to add hair, hats, jackets and other 3D details.",
  "Check it in the animated preview (walk, run, fly…), then download the PNG and apply it in Minecraft.",
];

const description =
  "Design a Minecraft skin on an animated 3D model: paint pixel by pixel, import any player's skin by username, switch between Steve and Alex arms, and download a ready-to-use PNG.";

const jsonLd: Record<string, unknown>[] = [
  {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: "Minecraft Skin Creator",
    description,
    url: `${APP_URL}/tools/minecraft-skin-creator`,
    applicationCategory: "DesignApplication",
    operatingSystem: "Any (web browser)",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    isAccessibleForFree: true,
    featureList: [
      "Animated 3D preview: idle, walk, run, fly, wave, crouch, hit and swim",
      "Classic (Steve, 4px arms) and Slim (Alex, 3px arms) models",
      "Paint on the 64×64 texture or directly on the 3D model",
      "Base and overlay layers (hat, jacket, sleeves, pants)",
      "Pencil, eraser, fill, eyedropper, line, rectangle, select/move, texture brush and shading",
      "Mirror painting, undo/redo, flip and rotate",
      "Import by Minecraft username, PNG upload, drag and drop, paste; legacy 64×32 skins converted",
      "Download PNG, copy to clipboard, share link, 3D screenshot",
    ],
  },
  {
    "@context": "https://schema.org",
    "@type": "HowTo",
    name: "How to make a Minecraft skin",
    description: "Create a custom Minecraft skin in your browser and apply it in Java or Bedrock Edition.",
    tool: [{ "@type": "HowToTool", name: "Nxeon Minecraft Skin Creator" }],
    step: steps.map((text, i) => ({ "@type": "HowToStep", position: i + 1, name: text.split(" — ")[0].replace(/[.,].*$/, ""), text })),
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="minecraft-skin-creator"
        category="Minecraft tool"
        title="Minecraft Skin Creator"
        description={description}
        facts={["Free", "No signup", "Editing runs in your browser"]}
        about={[
          {
            heading: "A Minecraft skin editor with a live 3D preview",
            body: (
              <>
                <p>
                  A Minecraft skin is a small 64×64 PNG that wraps around your character. This skin creator shows
                  that texture flat, with every body part and face outlined, right next to an animated 3D model
                  that updates as you paint — so you always know exactly where a pixel will land. Click any body
                  part on the model to jump straight to it, or switch on painting mode and draw on the 3D character
                  itself.
                </p>
                <p>
                  Everything a pixel artist needs is here: pencil and eraser with brush sizes, flood fill that stays
                  inside the face you click, eyedropper, lines, rectangles, a select-and-move tool with flip and
                  rotate, a texture brush for natural-looking noise, shading, mirror painting for symmetrical
                  designs, and unlimited undo while you work.
                </p>
              </>
            ),
          },
          {
            heading: "Base layer, overlay layer and the two arm models",
            body: (
              <ul>
                <li><b>Base layer</b> — the body itself. Minecraft draws it fully opaque, so the editor keeps it solid and warns you about any transparent base pixels.</li>
                <li><b>Overlay layer</b> — the hat, jacket, sleeves and pants that float just outside the body. Transparency works here: use it for hair, hoods, visors and armour.</li>
                <li><b>Classic vs Slim</b> — Classic (Steve) arms are 4 pixels wide, Slim (Alex) arms are 3. Switch at any time and the preview, guides and tools follow.</li>
              </ul>
            ),
          },
          {
            heading: "Remix any player's skin",
            body: (
              <p>
                Type a Minecraft Java username to load that player&apos;s current skin and cape, upload a PNG from
                your computer, or drag and drop and paste one in. Old 64×32 skins are converted automatically. When
                you&apos;re done, download the PNG, copy it, or copy a share link that carries the whole skin inside
                the link — nothing is uploaded or stored. Want to show it off? Run your own world on a{" "}
                <Link href="/minecraft-server-hosting">Minecraft server</Link>, start with a{" "}
                <Link href="/free-minecraft">free Minecraft server</Link>, or check any server with our{" "}
                <Link href="/tools/minecraft-server-status">Minecraft server status checker</Link>.
              </p>
            ),
          },
        ]}
        steps={steps}
        faq={faq}
        related={[
          { label: "Minecraft Server Status Checker", href: "/tools/minecraft-server-status" },
          { label: "Server Size Calculator", href: "/tools/server-size-calculator" },
          ...relatedTools("minecraft-skin-creator").filter((r) => !/minecraft-server-status|server-size-calculator/.test(r.href)).slice(0, 2),
        ]}
        jsonLd={jsonLd}
        cta={{
          title: "Show your skin off on your own server",
          copy: "Run a Minecraft server for you and your friends — Java or Bedrock, mods and plugins, full file access — or start on a free Minecraft server and upgrade later.",
          primary: { label: "Deploy a Minecraft server", href: "/minecraft-server-hosting" },
          secondary: { label: "Get a free Minecraft server", href: "/free-minecraft" },
          productRoute: "minecraft",
        }}
      >
        <SkinCreatorLazy variant="nxm" />
      </ToolShell>
    </>
  );
}

