import { test, after } from "node:test";
import assert from "node:assert/strict";
import { GET } from "../app/api/tools/mc-skin/route.ts";

/**
 * GET /api/tools/mc-skin end to end, with Mojang mocked at the global fetch:
 * validation before any network call, the JSON contract the editor reads,
 * error → status mapping, and the per-IP throttle.
 */
const realFetch = globalThis.fetch;
after(() => { globalThis.fetch = realFetch; });

const UUID = "0123456789abcdef0123456789abcdef";
const HASH = "d".repeat(64);
function png64(): Uint8Array {
  const b = new Uint8Array(45);
  b.set([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 13, 0x49, 0x48, 0x44, 0x52, 0, 0, 0, 64, 0, 0, 0, 64, 8, 6]);
  return b;
}
let calls: string[] = [];
globalThis.fetch = (async (input: string | URL | Request) => {
  const url = String(input);
  calls.push(url);
  if (url === "https://api.mojang.com/users/profiles/minecraft/FixturePlayer") return Response.json({ id: UUID, name: "FixturePlayer" });
  if (url.startsWith("https://api.mojang.com/")) return new Response(null, { status: 204 });
  if (url === `https://sessionserver.mojang.com/session/minecraft/profile/${UUID}`) {
    const value = Buffer.from(JSON.stringify({ textures: { SKIN: { url: `http://textures.minecraft.net/texture/${HASH}` } } })).toString("base64");
    return Response.json({ properties: [{ name: "textures", value }] });
  }
  if (url === `https://textures.minecraft.net/texture/${HASH}`) return new Response(png64());
  throw new Error(`unexpected ${url}`);
}) as typeof fetch;

const req = (username: string, ip = "203.0.113.9") =>
  new Request(`http://localhost/api/tools/mc-skin?username=${encodeURIComponent(username)}`, { headers: { "x-real-ip": ip } });

test("valid fixture player -> skin data URL + model", async () => {
  calls = [];
  const res = await GET(req("FixturePlayer"));
  assert.equal(res.status, 200);
  const j = await res.json();
  assert.equal(j.ok, true);
  assert.equal(j.name, "FixturePlayer");
  assert.equal(j.model, "classic");
  assert.match(j.skin, /^data:image\/png;base64,/);
  assert.equal(j.cape, null);
  assert.equal(calls.length, 3);
});

test("bad usernames are 400 without touching the network", async () => {
  calls = [];
  for (const u of ["", "has space", "../x", "a".repeat(17), "http://evil"]) {
    const res = await GET(req(u, "203.0.113.10"));
    assert.equal(res.status, 400, u);
    assert.equal((await res.json()).error, "invalid_username");
  }
  assert.equal(calls.length, 0);
});

test("unknown player -> 404 unknown_username", async () => {
  const res = await GET(req("NobodyHere", "203.0.113.11"));
  assert.equal(res.status, 404);
  assert.equal((await res.json()).error, "unknown_username");
});

test("per-IP throttle: the 21st request in a minute is 429", async () => {
  let last = 0;
  for (let i = 0; i < 21; i++) last = (await GET(req("FixturePlayer", "198.51.100.77"))).status;
  assert.equal(last, 429);
  // another client is unaffected
  assert.equal((await GET(req("FixturePlayer", "198.51.100.78"))).status, 200);
});

