// Playwright verification of the skin creator component (standalone harness; Mojang/our API mocked).
const { chromium } = require("/opt/nxeon/node_modules/playwright");
const http = require("http");
const fs = require("fs");
const path = require("path");
const zlib = require("zlib");

const WWW = path.join(__dirname, "www");
const OUT = path.join(__dirname, "shots");
fs.mkdirSync(OUT, { recursive: true });
const PORT = 3119;

// ── tiny PNG codec (8-bit RGBA) ────────────────────────────────────────────
const crcT = new Int32Array(256).map((_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c; });
const crc = (b) => { let c = -1; for (const x of b) c = crcT[(c ^ x) & 255] ^ (c >>> 8); return (c ^ -1) >>> 0; };
function chunk(type, data) { const l = Buffer.alloc(4); l.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type), data]); const c = Buffer.alloc(4); c.writeUInt32BE(crc(td)); return Buffer.concat([l, td, c]); }
function encodePng(w, h, rgba) {
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) rgba.copy(raw, y * (w * 4 + 1) + 1, y * w * 4, (y + 1) * w * 4);
  const text = chunk("tEXt", Buffer.from("Comment\0secret-metadata"));
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk("IHDR", ihdr), text, chunk("IDAT", zlib.deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]);
}
function decodePng(buf) {
  let o = 8, w = 0, h = 0, ct = 0; const idat = []; const chunks = [];
  while (o < buf.length) { const len = buf.readUInt32BE(o); const type = buf.toString("ascii", o + 4, o + 8); const d = buf.subarray(o + 8, o + 8 + len); chunks.push(type);
    if (type === "IHDR") { w = d.readUInt32BE(0); h = d.readUInt32BE(4); ct = d[9]; if (d[8] !== 8) throw new Error("bitdepth"); }
    if (type === "IDAT") idat.push(d); o += 12 + len; }
  const bpp = ct === 6 ? 4 : ct === 2 ? 3 : (() => { throw new Error("colortype " + ct); })();
  const raw = zlib.inflateSync(Buffer.concat(idat)); const stride = w * bpp; const out = Buffer.alloc(w * h * 4); const prev = Buffer.alloc(stride); const cur = Buffer.alloc(stride);
  for (let y = 0; y < h; y++) { const f = raw[y * (stride + 1)]; raw.copy(cur, 0, y * (stride + 1) + 1, (y + 1) * (stride + 1));
    for (let i = 0; i < stride; i++) { const a = i >= bpp ? cur[i - bpp] : 0, b = prev[i], c = i >= bpp ? prev[i - bpp] : 0; let v = cur[i];
      if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1; else if (f === 4) { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      cur[i] = v & 255; }
    for (let x = 0; x < w; x++) { out[(y * w + x) * 4] = cur[x * bpp]; out[(y * w + x) * 4 + 1] = cur[x * bpp + 1]; out[(y * w + x) * 4 + 2] = cur[x * bpp + 2]; out[(y * w + x) * 4 + 3] = bpp === 4 ? cur[x * bpp + 3] : 255; }
    cur.copy(prev); }
  return { w, h, px: out, chunks };
}
const at = (img, x, y) => [...img.px.subarray((y * img.w + x) * 4, (y * img.w + x) * 4 + 4)];

// fixture skins
function fixture(w, h, fn) { const b = Buffer.alloc(w * h * 4); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) b.set(fn(x, y), (y * w + x) * 4); return b; }
// modern slim-ish fixture: head front solid green, everything else used = grey, arm 4th columns empty
const modern = fixture(64, 64, (x, y) => (x >= 8 && x < 16 && y >= 8 && y < 16) ? [0, 200, 0, 255] : (y >= 16 && y < 32) || y < 16 ? [120, 120, 120, 255] : [0, 0, 0, 0]);
const modernPng = encodePng(64, 64, modern);
// legacy 64x32: right leg outer side column 0 red, rest grey
const legacy = fixture(64, 32, (x, y) => (x === 0 && y >= 20) ? [255, 0, 0, 255] : [90, 90, 90, 255]);
const legacyPng = encodePng(64, 32, legacy);
fs.writeFileSync(path.join(__dirname, "legacy.png"), legacyPng);
fs.writeFileSync(path.join(__dirname, "big.png"), encodePng(128, 128, Buffer.alloc(128 * 128 * 4, 200)));

// ── static server ──────────────────────────────────────────────────────────
const TYPES = { ".html": "text/html", ".js": "application/javascript", ".css": "text/css", ".png": "image/png", ".txt": "text/plain" };
const server = http.createServer((req, res) => {
  const u = new URL(req.url, "http://x"); let p = path.join(WWW, decodeURIComponent(u.pathname));
  if (u.pathname === "/") p = path.join(WWW, "index.html");
  fs.readFile(p, (e, d) => { if (e) { res.writeHead(404); return res.end(); } res.writeHead(200, { "content-type": TYPES[path.extname(p)] ?? "application/octet-stream" }); res.end(d); });
}).listen(PORT, "127.0.0.1");

const results = [];
const check = (name, ok, extra = "") => { results.push(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? "  — " + extra : ""}`); };

(async () => {
  const browser = await chromium.launch({ args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
  try {
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 }, acceptDownloads: true, deviceScaleFactor: 1 });
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(String(e)));
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
    let apiCalls = 0;
    await page.route("**/api/tools/mc-skin**", async (route) => {
      apiCalls++;
      const u = new URL(route.request().url());
      const name = u.searchParams.get("username");
      if (name === "FixturePlayer") return route.fulfill({ json: { ok: true, name: "FixturePlayer", uuid: "0".repeat(32), model: "slim", skin: "data:image/png;base64," + modernPng.toString("base64"), cape: null } });
      return route.fulfill({ status: 404, json: { ok: false, error: "unknown_username" } });
    });
    await page.goto(`http://127.0.0.1:${PORT}/?v=nxm`);
    await page.waitForSelector(".skc-canvas");
    const ready = await page.waitForFunction(() => !document.querySelector(".skc-stage-msg") || document.querySelector(".skc-stage-fallback"), null, { timeout: 30000 }).then(() => true).catch(() => false);
    const webgl = !(await page.$(".skc-stage-fallback"));
    check("3D preview loaded (lazy skinview3d bundle)", ready && webgl, webgl ? "" : "fell back to flat view");
    const loadedScripts = await page.evaluate(() => [...document.scripts].map((s) => s.src).filter((s) => s.includes("skinview3d")));
    check("skinview3d script injected only when the viewer mounts", loadedScripts.length === 1, loadedScripts.join(","));

    const exportPng = async () => {
      const [dl] = await Promise.all([page.waitForEvent("download"), page.click("[data-action=download]")]);
      const p = await dl.path();
      return { img: decodePng(fs.readFileSync(p)), name: dl.suggestedFilename() };
    };
    const canvasPoint = async (tx, ty) => {
      const b = await page.locator(".skc-canvas").boundingBox();
      return { x: b.x + (tx + 0.5) * (b.width / 64), y: b.y + (ty + 0.5) * (b.height / 64) };
    };
    const clickTexel = async (tx, ty) => { const p = await canvasPoint(tx, ty); await page.mouse.click(p.x, p.y); };

    // ── draw pixels ──
    await page.click("[data-tool=pencil]");
    await page.fill(".skc-hex", "#ff0000");
    await clickTexel(10, 10);
    let { img, name } = await exportPng();
    check("download is a 64×64 PNG", img.w === 64 && img.h === 64, `${img.w}x${img.h} ${name}`);
    check("pencil paints the clicked texel", JSON.stringify(at(img, 10, 10)) === JSON.stringify([255, 0, 0, 255]), JSON.stringify(at(img, 10, 10)));
    check("export carries no metadata chunks", !img.chunks.includes("tEXt") && !img.chunks.includes("iTXt"), img.chunks.join(","));

    // drag a stroke
    const a = await canvasPoint(20, 22), b2 = await canvasPoint(26, 22);
    await page.fill(".skc-hex", "#0000ff");
    await page.mouse.move(a.x, a.y); await page.mouse.down(); await page.mouse.move(b2.x, b2.y, { steps: 6 }); await page.mouse.up();
    ({ img } = await exportPng());
    check("drag stroke paints a continuous line", [20, 21, 22, 23, 24, 25, 26].every((x) => at(img, x, 22)[2] === 255 && at(img, x, 22)[0] === 0));

    // mirror
    await page.keyboard.press("x");
    await page.fill(".skc-hex", "#00ff00");
    await page.locator(".skc-canvas").hover();
    await clickTexel(9, 12);
    ({ img } = await exportPng());
    check("mirror paints the opposite side (head front col 1 -> col 6)", at(img, 9, 12)[1] === 255 && at(img, 14, 12)[1] === 255, `${at(img, 14, 12)}`);
    await page.keyboard.press("x");

    // undo / redo
    await page.keyboard.press("Control+z");
    ({ img } = await exportPng());
    check("undo reverts the last stroke", at(img, 9, 12)[1] !== 255 && at(img, 14, 12)[1] !== 255);
    await page.keyboard.press("Control+Shift+z");
    ({ img } = await exportPng());
    check("redo re-applies it", at(img, 9, 12)[1] === 255);

    // fill confined to a face
    await page.click("[data-tool=fill]");
    await page.fill(".skc-hex", "#ffff00");
    await clickTexel(36, 24); // body back face (32..39, 20..31)
    ({ img } = await exportPng());
    check("fill stays inside the clicked face", at(img, 34, 22)[0] === 255 && at(img, 34, 22)[1] === 255 && !(at(img, 30, 24)[0] === 255 && at(img, 30, 24)[1] === 255));

    // model switch: slim makes the 4th arm column unused
    await page.click("[data-tool=pencil]");
    await page.click("button:has-text('Slim · 3px arms')");
    await page.fill(".skc-hex", "#ff00ff");
    await clickTexel(55, 25); // unused in slim (right arm back ends at 53)
    await clickTexel(44, 25); // right arm front, used in both
    ({ img } = await exportPng());
    check("slim: unused texel not paintable", !(at(img, 55, 25)[0] === 255 && at(img, 55, 25)[2] === 255), `${at(img, 55, 25)}`);
    check("slim: arm front paintable", at(img, 44, 25)[0] === 255 && at(img, 44, 25)[2] === 255);
    await page.click("button:has-text('Classic · 4px arms')");
    await clickTexel(55, 25);
    ({ img } = await exportPng());
    check("classic: 4th arm column paintable again", at(img, 55, 25)[0] === 255 && at(img, 55, 25)[2] === 255);

    // overlay-only layer mode blocks base painting
    await page.click("button:has-text('Overlay')  >> nth=0");
    await page.fill(".skc-hex", "#123456");
    await clickTexel(12, 12); // base head front
    await clickTexel(44, 12); // overlay hat front
    ({ img } = await exportPng());
    check("overlay mode: base untouched, overlay painted", JSON.stringify(at(img, 12, 12)) !== JSON.stringify([18, 52, 86, 255]) && at(img, 44, 12)[0] === 18, `${at(img, 44, 12)}`);
    await page.click("button:has-text('Both layers')");

    await page.screenshot({ path: path.join(OUT, "desktop-nxm.png"), fullPage: true });

    // ── 3D: click a part to jump; paint on the model ──
    if (webgl) {
      const stage = await page.locator(".skc-stage").boundingBox();
      const zoomBefore = await page.locator(".skc-canvas").evaluate((c) => c.style.width);
      // head is near the top-centre of the default framing
      await page.mouse.click(stage.x + stage.width / 2, stage.y + stage.height * 0.27);
      await page.waitForTimeout(300);
      const zoomAfter = await page.locator(".skc-canvas").evaluate((c) => c.style.width);
      check("clicking the 3D head jumps/zooms the editor", zoomAfter !== zoomBefore, `${zoomBefore} -> ${zoomAfter}`);
      await page.click("button:has-text('Fit')");
      await page.click("button:has-text('Paint on model')");
      await page.fill(".skc-hex", "#ff8000");
      const before = (await exportPng()).img;
      await page.mouse.click(stage.x + stage.width / 2, stage.y + stage.height * 0.27);
      const after = (await exportPng()).img;
      let changed = [];
      for (let y = 0; y < 16; y++) for (let x = 0; x < 64; x++) if (JSON.stringify(at(before, x, y)) !== JSON.stringify(at(after, x, y))) changed.push([x, y, at(after, x, y)]);
      check("paint on the 3D model changes a head texel to the brush colour", changed.length > 0 && changed.every(([, , c]) => c[0] === 255 && c[1] === 128 && c[2] === 0), JSON.stringify(changed.slice(0, 3)));
      // with default zoom and camera, the centre of the head is the front face (x 8..15 or overlay 40..47)
      check("3D pick lands on the head's FRONT face", changed.length > 0 && changed.every(([x, y]) => y >= 8 && y < 16 && ((x >= 8 && x < 16) || (x >= 40 && x < 48))), JSON.stringify(changed.map(([x, y]) => [x, y])));
      await page.click("button:has-text('Painting on model')");
      await page.locator(".skc-stage").screenshot({ path: path.join(OUT, "stage.png") });
      const [shot] = await Promise.all([page.waitForEvent("download"), page.click("button:has-text('3D screenshot')")]);
      const sImg = decodePng(fs.readFileSync(await shot.path()));
      check("3D screenshot downloads a PNG of the stage", sImg.w > 100 && sImg.h > 100, `${sImg.w}x${sImg.h}`);
      // animation switch doesn't throw
      for (const lbl of ["Walk", "Run", "Fly", "Swim", "Still"]) await page.click(`.skc-vctl button:has-text('${lbl}')`);
      check("switching animations raises no errors", errors.length === 0, errors.join(" | "));
    }

    // ── import by username (API mocked) ──
    await page.fill("input[aria-label='Minecraft Java username']", "bad name!");
    await page.click("button:has-text('Get skin')");
    await page.waitForSelector(".skc-toast.show.err");
    check("invalid username rejected client-side (no API call)", apiCalls === 0);
    await page.fill("input[aria-label='Minecraft Java username']", "FixturePlayer");
    await page.click("button:has-text('Get skin')");
    await page.waitForFunction(() => document.querySelector(".skc-toast")?.textContent?.includes("Imported"));
    ({ img, name } = await exportPng());
    check("username import loads the fixture skin", JSON.stringify(at(img, 10, 10)) === JSON.stringify([0, 200, 0, 255]), `${at(img, 10, 10)}`);
    check("username import switches to the player's model (slim)", await page.locator("button:has-text('Slim · 3px arms')").getAttribute("aria-pressed") === "true");
    check("export file named after the player", name === "FixturePlayer.png", name);
    await page.fill("input[aria-label='Minecraft Java username']", "NoSuchPlayer");
    await page.click("button:has-text('Get skin')");
    await page.waitForFunction(() => document.querySelector(".skc-toast")?.textContent?.includes("No Minecraft"));
    check("unknown username shows a clear error", true);

    // ── upload: legacy 64x32 auto-convert, size rejection ──
    await page.setInputFiles(".skc-panel input[type=file] >> nth=0", path.join(__dirname, "legacy.png"));
    await page.waitForFunction(() => document.querySelector(".skc-toast")?.textContent?.includes("converted"));
    ({ img } = await exportPng());
    check("legacy 64×32 upload converted (right leg mirrored onto left leg)", JSON.stringify(at(img, 0, 20)) === "[255,0,0,255]" && JSON.stringify(at(img, 27, 52)) === "[255,0,0,255]", `${at(img, 27, 52)}`);
    await page.setInputFiles(".skc-panel input[type=file] >> nth=0", path.join(__dirname, "big.png"));
    await page.waitForFunction(() => document.querySelector(".skc-toast")?.textContent?.includes("128×128"));
    check("wrong-size upload rejected with its size", true);

    // ── share link round trip ──
    await ctx.grantPermissions(["clipboard-read", "clipboard-write"], { origin: `http://127.0.0.1:${PORT}` });
    await page.click("button:has-text('Copy share link')");
    const link = await page.evaluate(() => navigator.clipboard.readText());
    const p2 = await ctx.newPage();
    await p2.goto(link);
    await p2.waitForFunction(() => document.querySelector(".skc-toast")?.textContent?.includes("shared link"));
    const [dl2] = await Promise.all([p2.waitForEvent("download"), p2.click("[data-action=download]")]);
    const shared = decodePng(fs.readFileSync(await dl2.path()));
    check("share link (fragment) reproduces the exact skin", Buffer.compare(shared.px, img.px) === 0, `${link.length} chars, hash-only: ${new URL(link).search === ""}`);
    await p2.close();

    // ── templates ──
    await page.click(".skc-tpl >> nth=2");
    ({ img } = await exportPng());
    check("template loads (opaque base)", at(img, 8, 8)[3] === 255);

    check("no page errors overall", errors.length === 0, errors.slice(0, 3).join(" | "));

    // ── screenshots: mobile + nexion (dark, light) ──
    const m = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
    const mp = await m.newPage();
    await mp.goto(`http://127.0.0.1:${PORT}/?v=nxm`);
    await mp.waitForSelector(".skc-canvas"); await mp.waitForTimeout(2500);
    const overflow = await mp.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
    check("mobile 390px: no horizontal page overflow", !overflow);
    // touch tap paints
    const cb = await mp.locator(".skc-canvas").boundingBox();
    await mp.fill(".skc-hex", "#ff0000");
    await mp.touchscreen.tap(cb.x + 10.5 * cb.width / 64, cb.y + 10.5 * cb.height / 64);
    await mp.screenshot({ path: path.join(OUT, "mobile-nxm.png"), fullPage: true });
    const tapPix = await mp.evaluate(() => { const c = document.querySelector(".skc-canvas"); return [c.clientWidth]; });
    check("mobile: editor canvas fits the width", tapPix[0] <= 390, `${tapPix[0]}px`);
    await m.close();

    const n = await browser.newContext({ viewport: { width: 1280, height: 1000 } });
    const np = await n.newPage();
    await np.goto(`http://127.0.0.1:${PORT}/?v=nexion`); await np.waitForSelector(".skc-canvas"); await np.waitForTimeout(2500);
    await np.screenshot({ path: path.join(OUT, "desktop-nexion.png"), fullPage: false });
    await np.goto(`http://127.0.0.1:${PORT}/?v=nexion&theme=light`); await np.waitForSelector(".skc-canvas"); await np.waitForTimeout(2500);
    await np.screenshot({ path: path.join(OUT, "desktop-nexion-light.png"), fullPage: false });
    await n.close();
  } catch (e) {
    results.push("CRASH " + (e && e.stack || e));
  } finally {
    await browser.close();
    server.close();
    console.log(results.join("\n"));
  }
})();

